int main(bool hard) /************** MAIN **************/
{
	if(!hard){ SYS_hardReset(); } //Previne bug do Reset //hpig 1.1

    //Inicializacao da VDP (Video Display Processor)
	SYS_disableInts();
	 VDP_init();                    //Inicializa a VDP (Video Display Processor)
	 VDP_setScreenWidth320();       //Resolucao padrao de 320x224 (Largura)
	 VDP_setScreenHeight224();      //Resolucao padrao de 320x224 (Altura)
	 VDP_setPlaneSize(64,32,TRUE);  //Recomendado para BGs grandes
	 VDP_setTextPlane(BG_A);        //Textos serao desenhados no BG_A
	 VDP_setTextPalette(PAL1);      //Textos serao desenhados com a ultima cor da PAL0
     SPR_init();       				// Inicia a engine de sprites;
	 VDP_setBackgroundColor(0);     //Range 0-63 //4 Paletas de 16 cores = 64 cores
	SYS_enableInts();
	KLog_S1("debug = ", LIB_DEBUG);
	
	
	fase = 1; //manter o valor igual a 1
	faseMAX = MAX_FASES-1; //configurado para o número máximo de fases

	isPaused = FALSE;
	gRoom = R_TELA_DISCLAIMER;

	//Escolha do personagem em cada fase"
	characterFase[1] = ID_RYO;
	characterFase[2] = ID_KIM;
	characterFase[3] = ID_KYO;
	characterFase[4] = ID_TERRY;
	characterFase[5] = ID_MAI;
	characterFase[6] = ID_RALF;
	characterFase[7] = ID_IORI;
	characterFase[8] = ID_ROBERT;
	characterFase[9] = ID_RUGAL;
	
    while(TRUE) /// LOOP PRINCIPAL ///
    {
        	 if(gRoom==R_TELA_DISCLAIMER){           ROOM_TELA_DISCLAIMER(); } //TELA HAMOOPIG
		else if(gRoom==R_TELA_MEGA){                 ROOM_TELA_MEGA(); } //TELA MEGA
		else if(gRoom==R_TELA_CREDITOS){             ROOM_TELA_CREDITOS(); } //TELA DE CREDITOS
		else if(gRoom==R_TELA_APRESENTACAO){         ROOM_TELA_APRESENTACAO(); } //TELA DE APRESENTACAO
		else if(gRoom==R_CHAR_SELECT){               ROOM_CHAR_SELECT(); } //CHAR SELECT
		else if(gRoom==R_STAGE_SELECT){              ROOM_STAGE_SELECT(); } //STAGE SELECT
		else if(gRoom==R_TELA_OPCOES){               ROOM_OPCOES(); } //TELA DE OPCOES
		else if(gRoom==R_DESCOMPRESSION){            ROOM_DESCOMPRESSION(); } //DESCOMPRESSION
		else if(gRoom==R_IN_GAME){                   ROOM_IN_GAME(); } //IN GAME
		else if(gRoom==R_AFTER_MATCH){               ROOM_AFTER_MATCH(); } //AFTER MATCH
		else if(gRoom==R_FINAL_RYO){   		         ROOM_FINAL_RYO(); } //FINAL RYO
		else if(gRoom==R_FINAL_RUGAL){               ROOM_FINAL_RUGAL(); } //FINAL RUGAL
		else if(gRoom==R_TELA_GAME_OVER){            ROOM_TELA_GAME_OVER(); } //TELA GAME OVER
		else if(gRoom==R_TELA_VERSUS){               ROOM_TELA_VERSUS(); } //TELA DE VERSUS
		else if(gRoom==R_TRAINING_MENU){             ROOM_TRAINING_MENU(); }

		//--- FINALIZACOES ---//
		//VDP_showFPS(1);        //Mostra a taxa de FPS
		//SPR_update();          //Atualiza (desenha) os sprites
        //SYS_doVBlankProcess(); //Wait for screen refresh and do all SGDK VBlank tasks
    }
	
    return 0;
}

//--- FUNCOES ---//

void PLAYER_STATE(u8 Player, u16 State)
{
	DEBUG_PRINT("funcao player state");

	P[Player].previousState = P[Player].state; //Guarda o estado antes de trocar para o novo estado			

	// if(P[Player].sprite != NULL)
	// {
	// 	SPR_releaseSprite(P[Player].sprite);
	// 	P[Player].sprite = NULL;
	// }
	P[Player].animRow        = 0;
	P[Player].animFrame      = 1;
	P[Player].animFrameTotal = 1;
	P[Player].frameTimeAtual = 1;
	P[Player].frameTimeTotal = 1;
	P[Player].animTimeAtual  = 1;
	P[Player].animTimeTotal  = 1;
	P[Player].dataAnim[1]    = 1;
	P[Player].state = State;
	
	FUNCTION_PLAY_SND(Player, State); //SOUND; SFX!


	//Reseta energia no training mode
	if(TREINO==TRUE &&
		(State==100 || State==200 || State==603 || State==604 || State==605 || State==607 || State==608 || State==410 || State==420))
	{
		P[Player].energiaBase = TOTAL_LIFE;
	}

	
	//Verifica se deve virar de lado
	if(
		!( //Nao vira o estado de aterrisagem de ataques especiais ou estados especificos
			State==660
		)
	  )
	{
		if(((State>=501 && State<=550) || State==110 || State==210) || //Vira de lado ao sofrer um acerto
			((State>=700 && State<=890) && P[Player].y >= gAlturaPiso) || //Vira de lado no inicio do ataques especiais no chao
			((State>=900 && State<=990) && P[Player].y >= gAlturaPiso) || //Vira de lado no inicio dos arremessos no chao
			((State>=101 && State<=106) || (State>=151 && State<=156) || (State>=201 && State<=206) || (State>=160 && State<=169)) //Vira de lado ao fazer ataques normais no chao
		  )
		{
			u8 enemy = 2;
			if(Player == 2){ enemy = 1; }

			if(((State>=501 && State<=550) || State==110 || State==210) && P[Player].y >= gAlturaPiso){
				if( (P[Player].direcao== 1 && ((P[Player].x + P[Player].dataMBox[0]) >= (P[enemy].x + P[enemy].dataMBox[2]))) ||
					(P[Player].direcao==-1 && ((P[Player].x + P[Player].dataMBox[2]) <= (P[enemy].x + P[enemy].dataMBox[0]))))
				{
					if(P[Player].direcao==1){ P[Player].direcao = -1; }else{ P[Player].direcao = 1; }
				}
			}else{
				if((P[Player].direcao==1 && P[Player].x > P[enemy].x) || (P[Player].direcao==-1 && P[Player].x < P[enemy].x)){
					if(P[Player].direcao==1){ P[Player].direcao = -1; }else{ P[Player].direcao = 1; }
				}
			}
		}
	}
	
	//--- DEBUG_CHARACTER_TEST ---// #ID:0
	if(P[Player].id==0)
	{
		if(State==100 || State==610){
			P[Player].y = gAlturaPiso;
			P[Player].w = 8;
			P[Player].h = 8;
			P[Player].axisX = P[Player].w/2;
			P[Player].axisY = P[Player].h;
			P[Player].dataAnim[1]  = 250;
			P[Player].animFrameTotal = 1;
			P[Player].sprite = SPR_addSpriteExSafe(&spr_point, P[Player].x-P[Player].axisX, P[Player].y-P[Player].axisY, TILE_ATTR(P[Player].paleta, FALSE, FALSE, FALSE), SPR_FLAG_AUTO_VISIBILITY | SPR_FLAG_AUTO_VRAM_ALLOC | SPR_FLAG_AUTO_TILE_UPLOAD );
		}
	}
	
	//==================================================================
	//Definicoes dos estados dos personagens
	switch(P[Player].id){
		case ID_RYO: STATES_RYO(Player, State); break;
		case ID_RUGAL: STATES_RUGAL(Player, State); break;
		case ID_KIM: STATES_KIM(Player, State); break;
		case ID_KYO: STATES_KYO(Player, State); break;
		case ID_KULA: STATES_KULA(Player, State); break;
		case ID_IORI: STATES_IORI(Player, State); break;
		case ID_RALF: STATES_RALF(Player, State); break;
		case ID_TERRY: STATES_TERRY(Player, State); break;
		case ID_MAI: STATES_MAI(Player, State); break;
		case ID_ROBERT: STATES_ROBERT(Player, State); break;
		case ID_LEONA: STATES_LEONA(Player, State); break;
		case ID_CRIS: STATES_CRIS(Player, State); break;

		case ID_RYO_EX: STATES_RYO(Player, State); break;
		case ID_RUGAL_EX: STATES_RUGAL(Player, State); break;
		case ID_KIM_EX: STATES_KIM(Player, State); break;
		case ID_KYO_EX: STATES_KYO(Player, State); break;
		case ID_KULA_EX: STATES_KULA(Player, State); break;
		case ID_IORI_EX: STATES_IORI(Player, State); break;
		case ID_RALF_EX: STATES_RALF(Player, State); break;
		case ID_TERRY_EX: STATES_TERRY(Player, State); break;
		case ID_MAI_EX: STATES_MAI(Player, State); break;
		case ID_ROBERT_EX: STATES_ROBERT(Player, State); break;
		case ID_LEONA_EX: STATES_LEONA(Player, State); break;
		case ID_CRIS_EX: STATES_CRIS(Player, State); break;
	}

	//==================================================================
	//Padroes
	//Colocando estes estados no chao
	if(State==100 || State==200 || State==552 || State==570 || State==606 || State==660 || (State>=610 && State<=616) || State==620 ||
		State==473)
	{
		P[Player].y = gAlturaPiso;
		P[Player].hSpeed = 0;
		P[Player].puloTimer = 0;
		P[Player].impulsoY = 0;
	}

	P[Player].hitboxStartAnimFrame = 0; //Identifica o primeiro frame que a hitbox ficou ativa

	//Desativar hitbox
	P[Player].dataHBox[0]=0; P[Player].dataHBox[1]=0; P[Player].dataHBox[2]=0; P[Player].dataHBox[3]=0;
	
	//guardFlag
	P[Player].guardFlag = GFT_BlockMid; //Assume por padrao que defende em pe ou abaixado
	//if( State==101 || State==102 || State==113 || State==104 || State==105 || State==106 || State==201 || State==204 ){ P[Player].guardFlag = GFT_BlockMid; }
	//if( State>=700 && State<=799 ){ P[Player].guardFlag = GFT_BlockMid; }
	if( State==202 || State==203 || State==205 || State==206 ){ P[Player].guardFlag = GFT_BlockLow; }
	if( State>=300 && State<=326 ){ P[Player].guardFlag = GFT_BlockHigh; }
	if( State>=900 && State<=929 ){ P[Player].guardFlag = GFT_Unblockable; } //arremessoP

	//Para verificar se pode defender o ataque no ar
	P[Player].canBlockAir = FALSE;
	if((State >= 301 && State <= 326) || (State >= 700 && State <= 799)){
		P[Player].canBlockAir = TRUE;
	}

	P[Player].counterAttack = 0;

	//stateType
	P[Player].stateType = STP_Stand;
	if((State>=200 && State<=210) || State==511 || State==512 || State==513)
	{
		P[Player].stateType = STP_Crouch;
	}
	if(P[Player].y<gAlturaPiso || State==550 || State==970 || State==971){ P[Player].stateType = STP_Air; }
	if(State==570){ P[Player].stateType = STP_Liedown; }
	
	//stateMoveType
	if (State==100 || State==200 || State==300 || State==310 || State==320 || State==410 || State==420 ||
	    State==601 || State==602 || State==607 || State==608)
	{
		P[Player].stateMoveType = SMT_Neutral;
		P[Player].hitCounter = 0;
		P[Player].control = TRUE;
		P[Player].shortJump = FALSE;
	} else {
		P[Player].control = FALSE;
	}

	//Inicio de pulos, aterrisagem de pulos, intro, vitoria, derrota, avanco, recuo ou levantando
	if (State==603 || State==604 || State==605 || State==606 || State==660 || (State>=610 && State<=615) || State==471 || State==472 || State==552)
	{
		P[Player].stateMoveType = SMT_Neutral;
		P[Player].hitCounter = 0;
		if(State==606){ P[Player].notThrowable = 0; } //Para permitir sofrer arremesso na aterrisagem de pulos
	}
	
	if ((State>=101 && State<=106) || (State>=151 && State<=156) || (State>=201 && State<=206) || (State>=301 && State<=306) || 
		(State>=311 && State<=316) || (State>=321 && State<=326) || (State>=700 && State<=899) || (State>=160 && State<=169) ||
		(State>=170 && State<=179))
	{
		P[Player].stateMoveType = SMT_Attack;
		P[Player].attackContact = FALSE;
		P[Player].hitContact = FALSE;
	}

	if (State>=900 && State<=990){ //Arremessos
		P[Player].stateMoveType = SMT_Neutral;
		P[Player].attackContact = FALSE;
		P[Player].hitContact = FALSE;
	}

	P[Player].superStart = FALSE;
	if(State==800){
		P[Player].superStart = TRUE;
	}

	if (State==300 || State==310 || State==320) {
		P[Player].y -= 1;
		P[Player].puloTimer = 1;
		P[Player].jumpDirection = 0; //No lugar
		if(State==320){ P[Player].jumpDirection = P[Player].direcao; } //Para frente
		if(State==310){ P[Player].jumpDirection = P[Player].direcao *-1; } //Para tras
	}

	if (State==330) { //Depois de defender no ar
		P[Player].stateMoveType = SMT_Neutral;
		P[Player].hitCounter = 0;
		P[Player].control = TRUE;
		P[Player].cicloInteracoesGravidadeCont = 0;
		P[Player].gravidadeY = gravidadePadrao;
	}

	if(P[Player].state==339){ //Defesa no ar
		P[Player].cicloInteracoesGravidadeCont = 0;
		P[Player].gravidadeY = gravidadePadrao;
	}

	if(P[Player].state==340){ //Defesa no ar
		P[Player].cicloInteracoesGravidadeCont = 0;
		P[Player].gravidadeY = gravidadePadrao;
		P[Player].impulsoY = 0;
		P[Player].jumpDirection = P[Player].direcao *-1; //Para tras
	}

	if (State == 360) { //Recuperacao no ar
		P[Player].stateMoveType = SMT_Neutral;
		P[Player].hitCounter = 0;
		P[Player].cicloInteracoesGravidadeCont = 0;
		P[Player].gravidadeY = gravidadePadrao;
		P[Player].impulsoY = -3;
		P[Player].recovery = FALSE;
	}

	//Força do ataque
	P[Player].attackStrength = ATK_NORMAL_NONE; //Assume que nao esta atacando
	//Ataques normais fracos
	if (State == 101 || State == 104 || State == 151 || State == 154 || 
	    State == 201 || State == 204 || State == 301 || State == 304 ||
		State == 311 || State == 314 || State == 321 || State == 324)
	{
		P[Player].attackStrength = ATK_NORMAL_WEAK;

	} //Ataques normais medios
	else if (State == 102 || State == 105 || State == 152 || State == 155 || State == 165 ||
	    	 State == 202 || State == 205 || State == 302 || State == 305 ||
			 State == 312 || State == 315 || State == 322 || State == 325)
	{
		P[Player].attackStrength = ATK_NORMAL_MEDIUM;

	} //Ataques normais fortes
	else if (State == 103 || State == 106 || State == 153 || State == 156 || State == 160 ||
	         State == 203 || State == 206 || State == 303 || State == 306 || State == 166 ||
		     State == 313 || State == 316 || State == 323 || State == 326 || State == 170)
	{
		P[Player].attackStrength = ATK_NORMAL_STRONG;

	} //Ataques speciais ou supers
	else if (State >= 700 && State <= 899)
	{
		P[Player].attackStrength = ATK_SPECIAL;
	}

	if (State>=900 && State<=990) { //Arremessos
		P[Player].attackStrength = ATK_SPECIAL;
	}

	P[Player].hurtboxEqualsHitbox = FALSE;
	if ((State >= 101 && State <= 106) || (State >= 151 && State <= 156) || (State >= 201 && State <= 206) ||
		(State >= 301 && State <= 306) || (State >= 311 && State <= 316) || (State >= 321 && State <= 326)
	   )
	{
		P[Player].hurtboxEqualsHitbox = TRUE;
	}

	if (State == 550) {
		P[Player].cicloInteracoesGravidadeCont = 0;
		P[Player].gravidadeY = gravidadePadrao;
		P[Player].impulsoY = P[Player].attackImpulseY;
		P[Player].isToHFlip = FALSE;
	}

	P[Player].allowsReversal = FALSE;
	if (State == 552 || State == 501 || State == 502 || State == 503 ||
		State == 506 || State == 507 || State == 508 || 
		State == 511 || State == 512 || State == 513 ||
		((P[Player].state == 109 || P[Player].state == 209) && P[Player].cancelDefense == FALSE)
	   )
	{
		P[Player].allowsReversal = TRUE;
	}

	if (State == 990) { P[Player].isToHFlip = TRUE; } //Para virar o sprite na horizontal
	if (State == 552) { P[Player].isToHFlip = FALSE; } //Para voltar o sprite ao normal
	if (State == 551) { camShakeControl = 1; } //Ativa o efeito de tremer a camera

	//Se o personagem morreu aumenta o tempo que ele fica no chao
	if (State == 570 && P[Player].energiaBase == 0) {
		P[Player].dataAnim[1] = 100;
		P[Player].isToHFlip = FALSE;
	}
	
	if (State == 110 || State == 210) {
			 if (P[Player].defenseLevel == WEAK  ) { P[Player].dataAnim[1]  = 9; }
		else if (P[Player].defenseLevel == MEDIUM) { P[Player].dataAnim[1]  = 13; }
		else if (P[Player].defenseLevel == FIERCE) { P[Player].dataAnim[1]  = 17; }
	}

	for (u8 f = 1; f <= P[Player].animFrameTotal; f++) {
		if (P[Player].animTimeTotal < 4200200200) { P[Player].animTimeTotal += P[Player].dataAnim[f]; }
	}
	P[Player].animTimeTotal -= 1; //Remove 1 porque foi inicializado com 1
	
	P[Player].slideTime1 = 0;
	P[Player].slideTime2 = 0;

	if (State>=500 && State<509) {
		P[Player].slideTime1 = fix16ToInt(fix16Mul(FIX16(P[Player].animTimeTotal), FIX16(0.5)));
		P[Player].slideTime2 = fix16ToInt(fix16Mul(FIX16(P[Player].animTimeTotal), FIX16(0.75)));
	}
	if (State>=511 && State<550) {
		P[Player].slideTime1 = fix16ToInt(fix16Mul(FIX16(P[Player].animTimeTotal), FIX16(0.5)));
		P[Player].slideTime2 = fix16ToInt(fix16Mul(FIX16(P[Player].animTimeTotal), FIX16(0.75)));
	}

	if (State==110 || State==210) {
		P[Player].slideTime1 = fix16ToInt(fix16Mul(FIX16(P[Player].animTimeTotal), FIX16(0.8)));
		P[Player].slideTime2 = P[Player].animTimeTotal;
	}

	P[Player].frameTimeTotal  = P[Player].dataAnim[1];

	FUNCTION_APPLY_FLIP(Player, P[Player].isToHFlip);

	if(P[Player].sprite != NULL){
		SPR_setAnimAndFrame(P[Player].sprite,  P[Player].animRow, P[Player].animFrame-1);
	}else{
		if(Player==1){ DEBUG_PRINT("Player 1 sprite is NULL"); }
		else if(Player==2){ DEBUG_PRINT("Player 2 sprite is NULL"); }
	}

	// Cabeças do Chonrei e do Chonshu
	if(GE[21 + Player].sprite != NULL){
		SPR_setAnimAndFrame(GE[21 + Player].sprite,  P[Player].animRow, P[Player].animFrame-1);
	}else{
		if(Player==1){ DEBUG_PRINT("Player 1 cabeca sprite is NULL"); }
		else if(Player==2){ DEBUG_PRINT("Player 2 cabeca sprite is NULL"); }
	}

	FUNCTION_DEPTH(Player); //Define a prioridade de desenho
	FUNCTION_SPR_POSITION(); //Define a posicao do Sprite
	FUNCTION_FSM_HITBOXES(Player); //Atualiza as Hurt / Hitboxes
}

void FUNCTION_INITIALIZATION()
{
	DEBUG_PRINT("funcao inicializacao");
	
	gPodeMover = 0;
	gPauseKoTimer = 0;
	gSoundKo = 1;
	gRoundState = RS_PREINTRO;
	gRound = 1; //Round Number

	//Para verificar a vantagem ou desvantagem em relacao aos frames
	frameAdvCounterP1 = 0;
	lastFrameAdvCounterP1 = 0;
	frameAdvCounterP2 = 0;
	lastFrameAdvCounterP2 = 0;
		
	isPaused = FALSE;
	superPause = FALSE;
	gPauseSystem = FALSE;

	gBG_Choice = CENARIO_JAPAO;//hack do cenario

	//Inicia cenário
	if(gBG_Choice==CENARIO_OMEGA)
	{
		VDP_setScrollingMode(HSCROLL_LINE, VSCROLL_PLANE);
	}else{
		VDP_setScrollingMode(HSCROLL_TILE, VSCROLL_PLANE);
	}

	gInd_tileset = CEN_init(gBG_Choice);
	VDP_setBackgroundColor(16);
	gBG_Width = 512;
	gScrollValue = (gBG_Width-320)/2;

	gAlturaPiso = 208; //(224/20)*19;
	
	gMeioDaTela = 256-160;
	camPosX = gMeioDaTela;

	// if(gBG_Choice==CENARIO_BRASIL ){// tirando a prioridade para o mato aparecer na frente
	// 	SPR_setPriority(P[1].sprite, FALSE);
	// 	SPR_setPriority(P[2].sprite, FALSE);
	// }
	SPR_setPriority(P[1].sprite, FALSE);
	SPR_setPriority(P[2].sprite, FALSE);

	//Movimenta o BG
	VDP_setHorizontalScrollVSync(BG_A, camPosX*-1);
	VDP_setHorizontalScrollVSync(BG_B, (camPosX*-1)/2);
	guardCancelP1_Count = 0;
	guardCancelP2_Count = 0;
	
	P1_previousEnergySP = P[1].energiaSP;
	P2_previousEnergySP = P[2].energiaSP;
	P1_Ind_tileset_EnergySP = 0;
	P2_Ind_tileset_EnergySP = 0;

	//Inicializacap do buffer de inputs de comandos
	for (u8 i = 0; i < MAX_INPUT_BUFFER; i++) {
		P[1].dirInputArray[i] = 0;
		P[1].dirInputTimer[i] = 0;

		P[2].dirInputArray[i] = 0;
		P[2].dirInputTimer[i] = 0;
	}

	for(u8 i=1; i<=2; i++){
		currentJoyState[i] = 0;
		previousJoyState[i] = 0;
	}

	gClockTimer=60; //Relogio, timer de 1 seg
	gClockLTimer=9; //Digito esquerdo do Relogio
	gClockRTimer=9; //Digito direito do Relogio

	
	if(Rect1BB1_Q1 == NULL){ Rect1BB1_Q1 = SPR_addSpriteEx(&spr_rect_bb, -8, -8, TILE_ATTR(PAL1, FALSE, FALSE, FALSE), SPR_FLAG_AUTO_VISIBILITY | SPR_FLAG_AUTO_TILE_UPLOAD); }else{ DEBUG_PRINT("Rect1BB1_Q1 != NULL"); }
	if(Rect1BB1_Q2 == NULL){ Rect1BB1_Q2 = SPR_addSpriteEx(&spr_rect_bb, -8, -8, TILE_ATTR(PAL1, FALSE, FALSE, FALSE), SPR_FLAG_AUTO_VISIBILITY | SPR_FLAG_AUTO_TILE_UPLOAD); }else{ DEBUG_PRINT("Rect1BB1_Q2 != NULL"); }
	if(Rect1BB1_Q3 == NULL){ Rect1BB1_Q3 = SPR_addSpriteEx(&spr_rect_bb, -8, -8, TILE_ATTR(PAL1, FALSE, FALSE, FALSE), SPR_FLAG_AUTO_VISIBILITY | SPR_FLAG_AUTO_TILE_UPLOAD); }else{ DEBUG_PRINT("Rect1BB1_Q3 != NULL"); }
	if(Rect1BB1_Q4 == NULL){ Rect1BB1_Q4 = SPR_addSpriteEx(&spr_rect_bb, -8, -8, TILE_ATTR(PAL1, FALSE, FALSE, FALSE), SPR_FLAG_AUTO_VISIBILITY | SPR_FLAG_AUTO_TILE_UPLOAD); }else{ DEBUG_PRINT("Rect1BB1_Q4 != NULL"); }

	if(Rect1HB1_Q1 == NULL){ Rect1HB1_Q1 = SPR_addSpriteEx(&spr_rect_hb, -8, -8, TILE_ATTR(PAL1, FALSE, FALSE, FALSE), SPR_FLAG_AUTO_VISIBILITY | SPR_FLAG_AUTO_TILE_UPLOAD); }else{ DEBUG_PRINT("Rect1HB1_Q1 != NULL"); }
	if(Rect1HB1_Q2 == NULL){ Rect1HB1_Q2 = SPR_addSpriteEx(&spr_rect_hb, -8, -8, TILE_ATTR(PAL1, FALSE, FALSE, FALSE), SPR_FLAG_AUTO_VISIBILITY | SPR_FLAG_AUTO_TILE_UPLOAD); }else{ DEBUG_PRINT("Rect1HB1_Q2 != NULL"); }
	if(Rect1HB1_Q3 == NULL){ Rect1HB1_Q3 = SPR_addSpriteEx(&spr_rect_hb, -8, -8, TILE_ATTR(PAL1, FALSE, FALSE, FALSE), SPR_FLAG_AUTO_VISIBILITY | SPR_FLAG_AUTO_TILE_UPLOAD); }else{ DEBUG_PRINT("Rect1HB1_Q3 != NULL"); }
	if(Rect1HB1_Q4 == NULL){ Rect1HB1_Q4 = SPR_addSpriteEx(&spr_rect_hb, -8, -8, TILE_ATTR(PAL1, FALSE, FALSE, FALSE), SPR_FLAG_AUTO_VISIBILITY | SPR_FLAG_AUTO_TILE_UPLOAD); }else{ DEBUG_PRINT("Rect1HB1_Q4 != NULL"); }
	
	if(Rect2BB1_Q1 == NULL){ Rect2BB1_Q1 = SPR_addSpriteEx(&spr_rect_bb, -8, -8, TILE_ATTR(PAL1, FALSE, FALSE, FALSE), SPR_FLAG_AUTO_VISIBILITY | SPR_FLAG_AUTO_TILE_UPLOAD); }else{ DEBUG_PRINT("Rect2BB1_Q1 != NULL"); }
	if(Rect2BB1_Q2 == NULL){ Rect2BB1_Q2 = SPR_addSpriteEx(&spr_rect_bb, -8, -8, TILE_ATTR(PAL1, FALSE, FALSE, FALSE), SPR_FLAG_AUTO_VISIBILITY | SPR_FLAG_AUTO_TILE_UPLOAD); }else{ DEBUG_PRINT("Rect2BB1_Q2 != NULL"); }
	if(Rect2BB1_Q3 == NULL){ Rect2BB1_Q3 = SPR_addSpriteEx(&spr_rect_bb, -8, -8, TILE_ATTR(PAL1, FALSE, FALSE, FALSE), SPR_FLAG_AUTO_VISIBILITY | SPR_FLAG_AUTO_TILE_UPLOAD); }else{ DEBUG_PRINT("Rect2BB1_Q3 != NULL"); }
	if(Rect2BB1_Q4 == NULL){ Rect2BB1_Q4 = SPR_addSpriteEx(&spr_rect_bb, -8, -8, TILE_ATTR(PAL1, FALSE, FALSE, FALSE), SPR_FLAG_AUTO_VISIBILITY | SPR_FLAG_AUTO_TILE_UPLOAD); }else{ DEBUG_PRINT("Rect2BB1_Q4 != NULL"); }

	if(Rect2HB1_Q1 == NULL){ Rect2HB1_Q1 = SPR_addSpriteEx(&spr_rect_hb, -8, -8, TILE_ATTR(PAL1, FALSE, FALSE, FALSE), SPR_FLAG_AUTO_VISIBILITY | SPR_FLAG_AUTO_TILE_UPLOAD); }else{ DEBUG_PRINT("Rect2HB1_Q1 != NULL"); }
	if(Rect2HB1_Q2 == NULL){ Rect2HB1_Q2 = SPR_addSpriteEx(&spr_rect_hb, -8, -8, TILE_ATTR(PAL1, FALSE, FALSE, FALSE), SPR_FLAG_AUTO_VISIBILITY | SPR_FLAG_AUTO_TILE_UPLOAD); }else{ DEBUG_PRINT("Rect2HB1_Q2 != NULL"); }
	if(Rect2HB1_Q3 == NULL){ Rect2HB1_Q3 = SPR_addSpriteEx(&spr_rect_hb, -8, -8, TILE_ATTR(PAL1, FALSE, FALSE, FALSE), SPR_FLAG_AUTO_VISIBILITY | SPR_FLAG_AUTO_TILE_UPLOAD); }else{ DEBUG_PRINT("Rect2HB1_Q3 != NULL"); }
	if(Rect2HB1_Q4 == NULL){ Rect2HB1_Q4 = SPR_addSpriteEx(&spr_rect_hb, -8, -8, TILE_ATTR(PAL1, FALSE, FALSE, FALSE), SPR_FLAG_AUTO_VISIBILITY | SPR_FLAG_AUTO_TILE_UPLOAD); }else{ DEBUG_PRINT("Rect2HB1_Q4 != NULL"); }
	
	if(Rect1BB1_Q1 != NULL){ SPR_setVRAMTileIndex(Rect1BB1_Q1, 0x6FE); SPR_setDepth(Rect1BB1_Q1, TRUE); }else{ DEBUG_PRINT("Rect1BB1_Q1 == NULL"); }
	if(Rect1BB1_Q2 != NULL){ SPR_setVRAMTileIndex(Rect1BB1_Q2, 0x6FE); SPR_setHFlip(Rect1BB1_Q2, TRUE); }else{ DEBUG_PRINT("Rect1BB1_Q2 == NULL"); }
	if(Rect1BB1_Q3 != NULL){ SPR_setVRAMTileIndex(Rect1BB1_Q3, 0x6FE); SPR_setVFlip(Rect1BB1_Q3, TRUE); }else{ DEBUG_PRINT("Rect1BB1_Q3 == NULL"); }
	if(Rect1BB1_Q4 != NULL){ SPR_setVRAMTileIndex(Rect1BB1_Q4, 0x6FE); SPR_setHFlip(Rect1BB1_Q4, TRUE); SPR_setVFlip(Rect1BB1_Q4, TRUE); }else{ DEBUG_PRINT("Rect1BB1_Q4 == NULL"); }
	
	if(Rect1HB1_Q1 != NULL){ SPR_setVRAMTileIndex(Rect1HB1_Q1, 0x6FF); SPR_setDepth(Rect1HB1_Q1, 1); }else{ DEBUG_PRINT("Rect1HB1_Q1 == NULL"); }
	if(Rect1HB1_Q2 != NULL){ SPR_setVRAMTileIndex(Rect1HB1_Q2, 0x6FF); SPR_setHFlip(Rect1HB1_Q2, TRUE); }else{ DEBUG_PRINT("Rect1HB1_Q2 == NULL"); }
	if(Rect1HB1_Q3 != NULL){ SPR_setVRAMTileIndex(Rect1HB1_Q3, 0x6FF); SPR_setVFlip(Rect1HB1_Q3, TRUE); }else{ DEBUG_PRINT("Rect1HB1_Q3 == NULL"); }
	if(Rect1HB1_Q4 != NULL){ SPR_setVRAMTileIndex(Rect1HB1_Q4, 0x6FF); SPR_setHFlip(Rect1HB1_Q4, TRUE); SPR_setVFlip(Rect1HB1_Q4, TRUE); }else{ DEBUG_PRINT("Rect1HB1_Q4 == NULL"); }
	
	if(Rect2BB1_Q1 != NULL){ SPR_setVRAMTileIndex(Rect2BB1_Q1, 0x6FE); SPR_setDepth(Rect2BB1_Q1, TRUE); }else{ DEBUG_PRINT("Rect2BB1_Q1 == NULL"); }
	if(Rect2BB1_Q2 != NULL){ SPR_setVRAMTileIndex(Rect2BB1_Q2, 0x6FE); SPR_setHFlip(Rect2BB1_Q2, TRUE); }else{ DEBUG_PRINT("Rect2BB1_Q2 == NULL"); }
	if(Rect2BB1_Q3 != NULL){ SPR_setVRAMTileIndex(Rect2BB1_Q3, 0x6FE); SPR_setVFlip(Rect2BB1_Q3, TRUE); }else{ DEBUG_PRINT("Rect2BB1_Q3 == NULL"); }
	if(Rect2BB1_Q4 != NULL){ SPR_setVRAMTileIndex(Rect2BB1_Q4, 0x6FE); SPR_setHFlip(Rect2BB1_Q4, TRUE); SPR_setVFlip(Rect2BB1_Q4, TRUE); }else{ DEBUG_PRINT("Rect2BB1_Q4 == NULL"); }

	if(Rect2HB1_Q1 != NULL){ SPR_setVRAMTileIndex(Rect2HB1_Q1, 0x6FF); SPR_setDepth(Rect2HB1_Q1, 1); }else{ DEBUG_PRINT("Rect2HB1_Q1 == NULL"); }
	if(Rect2HB1_Q2 != NULL){ SPR_setVRAMTileIndex(Rect2HB1_Q2, 0x6FF); SPR_setHFlip(Rect2HB1_Q2, TRUE); }else{ DEBUG_PRINT("Rect2HB1_Q2 == NULL"); }
	if(Rect2HB1_Q3 != NULL){ SPR_setVRAMTileIndex(Rect2HB1_Q3, 0x6FF); SPR_setVFlip(Rect2HB1_Q3, TRUE); }else{ DEBUG_PRINT("Rect2HB1_Q3 == NULL"); }
	if(Rect2HB1_Q4 != NULL){ SPR_setVRAMTileIndex(Rect2HB1_Q4, 0x6FF); SPR_setHFlip(Rect2HB1_Q4, TRUE); SPR_setVFlip(Rect2HB1_Q4, TRUE); }else{ DEBUG_PRINT("Rect2HB1_Q4 == NULL"); }


	//Modo 1 vs 1: os IDs escolhidos na seleção já ficam em P[1].id e P[2].id.
	FUNCTION_INITIALIZE_PLAYERS();

	//area inicio dos sprites
	LOAD_ATLAS(1); //P1
	LOAD_ATLAS(2); //P2
	
	if(P[2].sprite != NULL){ SPR_setHFlip(P[2].sprite, TRUE); } //Gira o sprite do P2
	
	//Define a paleta dos personagens
	P[1].palID = cursorP1ColorChoice;
	P[2].palID = cursorP2ColorChoice;
	
	if(
		(
		((P[1].id==ID_TERRY  || P[1].id==ID_TERRY_EX)  && (P[2].id==ID_TERRY  || P[2].id==ID_TERRY_EX)) ||
		((P[1].id==ID_MAI    || P[1].id==ID_MAI_EX)    && (P[2].id==ID_MAI    || P[2].id==ID_MAI_EX)) ||
		((P[1].id==ID_KIM    || P[1].id==ID_KIM_EX)    && (P[2].id==ID_KIM    || P[2].id==ID_KIM_EX)) ||
		((P[1].id==ID_RYO    || P[1].id==ID_RYO_EX)    && (P[2].id==ID_RYO    || P[2].id==ID_RYO_EX)) ||
		((P[1].id==ID_ROBERT || P[1].id==ID_ROBERT_EX) && (P[2].id==ID_ROBERT || P[2].id==ID_ROBERT_EX)) ||
		((P[1].id==ID_KYO    || P[1].id==ID_KYO_EX)    && (P[2].id==ID_KYO    || P[2].id==ID_KYO_EX)) ||
		((P[1].id==ID_LEONA  || P[1].id==ID_LEONA_EX)  && (P[2].id==ID_LEONA  || P[2].id==ID_LEONA_EX)) ||
		((P[1].id==ID_RALF   || P[1].id==ID_RALF_EX)   && (P[2].id==ID_RALF   || P[2].id==ID_RALF_EX)) ||
		((P[1].id==ID_KULA   || P[1].id==ID_KULA_EX)   && (P[2].id==ID_KULA   || P[2].id==ID_KULA_EX)) ||
		((P[1].id==ID_CRIS   || P[1].id==ID_CRIS_EX)   && (P[2].id==ID_CRIS   || P[2].id==ID_CRIS_EX)) ||
		((P[1].id==ID_RUGAL  || P[1].id==ID_RUGAL_EX)  && (P[2].id==ID_RUGAL  || P[2].id==ID_RUGAL_EX)) ||
		((P[1].id==ID_IORI   || P[1].id==ID_IORI_EX)   && (P[2].id==ID_IORI   || P[2].id==ID_IORI_EX))
	  	) && P[1].palID==P[2].palID
	  )
	{
		//se ambos os players forem iguais e com a mesma paleta...
		P[1].palID=1; //Por padrao, P1 fica com a paleta 1
		P[2].palID=2; //Por padrao, P2 fica com a paleta 2 'cor alternativa'
	}

	const u16* pal_effect_P1 = GET_PALETTE_PER_CHARACTER(P[1].id, P[1].palID);
	PAL_setPalette(PAL2, pal_effect_P1, DMA);

	const u16* pal_effect_P2 = GET_PALETTE_PER_CHARACTER(P[2].id, P[2].palID);
	PAL_setPalette(PAL3, pal_effect_P2, DMA);

	//Intro diferente com 2 personagens iguais, by Rheo
	if(P[1].id!=P[2].id)
	{
		PLAYER_STATE(1,610);
		PLAYER_STATE(2,610);
	}else{
		PLAYER_STATE(1,610);
		PLAYER_STATE(2,616);
	}

	//AXIS
	if(GE[1].sprite){ SPR_releaseSprite(GE[1].sprite); GE[1].sprite = NULL; }
	if(GE[2].sprite){ SPR_releaseSprite(GE[2].sprite); GE[2].sprite = NULL; }
	GE[1].sprite = SPR_addSpriteExSafe(&spr_point, -8, -8, TILE_ATTR(PAL1, FALSE, FALSE, FALSE), SPR_FLAG_AUTO_VISIBILITY | SPR_FLAG_AUTO_VRAM_ALLOC | SPR_FLAG_AUTO_TILE_UPLOAD);
	GE[2].sprite = SPR_addSpriteExSafe(&spr_point, -8, -8, TILE_ATTR(PAL1, FALSE, FALSE, FALSE), SPR_FLAG_AUTO_VISIBILITY | SPR_FLAG_AUTO_VRAM_ALLOC | SPR_FLAG_AUTO_TILE_UPLOAD);
	
	if(GE[1].sprite != NULL)
	{
		SPR_setVRAMTileIndex(GE[1].sprite, 0x6fd); //define uma posicao especifica para o GFX na VRAM
		SPR_setDepth(GE[1].sprite, 1 );
		if(gDebug || activeShowHiboxes){ SPR_setVisibility(GE[1].sprite, VISIBLE); }else{ SPR_setVisibility(GE[1].sprite, HIDDEN); }
	}
	else{ DEBUG_PRINT("Error: GE[1].sprite is NULL"); }

	if(GE[2].sprite != NULL)
	{
		SPR_setVRAMTileIndex(GE[2].sprite, 0x6fd); //define uma posicao especifica para o GFX na VRAM
		SPR_setDepth(GE[2].sprite, 2 );
		if(gDebug || activeShowHiboxes){ SPR_setVisibility(GE[2].sprite, VISIBLE); }else{ SPR_setVisibility(GE[2].sprite, HIDDEN); }
	}
	else{ DEBUG_PRINT("Error: GE[2].sprite is NULL"); }
	
	//Depth reservados para os personagens
	if(P[1].sprite != NULL){ SPR_setDepth(P[1].sprite, 5); }else{ DEBUG_PRINT("Error: P[1].sprite is NULL"); }
	if(P[2].sprite != NULL){ SPR_setDepth(P[2].sprite, 6); }else{ DEBUG_PRINT("Error: P[2].sprite is NULL"); }
}

