__attribute__((optimize("unroll-loops")))
void FUNCTION_INPUT_SYSTEM()
{
	DEBUG_PRINT("funcao input system");
	
	//Verificação dos estados dos inputs dos jogadores
	for (u8 player = 1; player <= 2; player++)
	{
        previousJoyState[player] = currentJoyState[player];

		if(player==1)
		{
			P1_START = FALSE;
			if(attractMode && (JOY_readJoypad(JOY_1) & BUTTON_START)){ P1_START = TRUE; }

			if(gRoom!=R_IN_GAME || (P[player].active_AI==FALSE && gRoom==R_IN_GAME)){
				currentJoyState[player] = JOY_readJoypad(JOY_1);
			}else if(P[player].active_AI==TRUE && gRoom==R_IN_GAME && gPodeMover){
				currentJoyState[player] = FUNCTION_ARTIFICIAL_INTELLIGENCE(1);
			}
		}
		else if(player==2)
		{
			P2_START = FALSE;
			if(attractMode && (JOY_readJoypad(JOY_2) & BUTTON_START)){ P2_START = TRUE; }

			if(gRoom!=R_IN_GAME || (P[player].active_AI==FALSE && gRoom==R_IN_GAME)){
				currentJoyState[player] = JOY_readJoypad(JOY_2);
			}else if(P[player].active_AI==TRUE && gRoom==R_IN_GAME && gPodeMover){
				currentJoyState[player] = FUNCTION_ARTIFICIAL_INTELLIGENCE(2);
			}
		}

		if(gameMode==GM_TRAINING && gRoom==R_IN_GAME){ FUNCTION_TRAINING_DUMMY(player); } //Para o boneco de treino

        for (u8 i = 0; i < NUM_BUTTONS; i++)
		{
            u16 button = buttons[i];

			if (!(currentJoyState[player] & button) && (previousJoyState[player] & button)) {
                key_JOY_status[player][i] = 3; //RELEASED
			} else if ((currentJoyState[player] & button) && (previousJoyState[player] & button)) {
                key_JOY_status[player][i] = 2; //HOLD
            } else if ((currentJoyState[player] & button) && !(previousJoyState[player] & button)) {
                key_JOY_status[player][i] = 1; //PRESSED
            } else if (!(currentJoyState[player] & button)) {
                key_JOY_status[player][i] = 0; //NONE
			}
        }

		//end of loop, assignments
		P[player].key_JOY_UP_status    = key_JOY_status[player][ 0]; //UP
		P[player].key_JOY_DOWN_status  = key_JOY_status[player][ 1]; //DOWN
		P[player].key_JOY_LEFT_status  = key_JOY_status[player][ 2]; //LEFT
		P[player].key_JOY_RIGHT_status = key_JOY_status[player][ 3]; //RIGHT
		P[player].key_JOY_A_status     = key_JOY_status[player][ 4]; //A
		P[player].key_JOY_B_status     = key_JOY_status[player][ 5]; //B
		P[player].key_JOY_C_status     = key_JOY_status[player][ 6]; //C
		P[player].key_JOY_X_status     = key_JOY_status[player][ 7]; //X
		P[player].key_JOY_Y_status     = key_JOY_status[player][ 8]; //Y
		P[player].key_JOY_Z_status     = key_JOY_status[player][ 9]; //Z
		P[player].key_JOY_START_status = key_JOY_status[player][10]; //START
		P[player].key_JOY_MODE_status  = key_JOY_status[player][11]; //MODE
    }

	P[1].commands = fightInputSystem(JOY_1);
	P[2].commands = fightInputSystem(JOY_2);

	for (u8 player = 1; player <= 2; player++)
	{
		//---InputTimerCountDown; InputArray
		u8 dirPressed=0;
		u8 dirReleased=0;
	
		if(P[player].key_JOY_UP_status   ==1){ dirPressed=8; }
		if(P[player].key_JOY_DOWN_status ==1){ dirPressed=2; }
		if(P[player].key_JOY_LEFT_status ==1){ dirPressed=4; }
		if(P[player].key_JOY_RIGHT_status==1){ dirPressed=6; }

		if(P[player].key_JOY_UP_status   ==3){ dirReleased=8; }
		if(P[player].key_JOY_DOWN_status ==3){ dirReleased=2; }
		if(P[player].key_JOY_LEFT_status ==3){ dirReleased=4; }
		if(P[player].key_JOY_RIGHT_status==3){ dirReleased=6; }

		if(dirPressed!=0)
		{
			// Mover os inputs no buffer para colocar o novo input no inicio, descarta o primeiro input que foi colocado no buffer anteriormente
			for (u8 i=MAX_INPUT_BUFFER-1; i>0 ; i--){
				P[player].dirInputArray[i] = P[player].dirInputArray[i-1];
				P[player].dirInputTimer[i] = P[player].dirInputTimer[i-1];
			}
			P[player].dirInputArray[0] = dirPressed;
			P[player].dirInputTimer[0] = 0;
		}

		if(dirReleased!=0)
		{
			if(dirReleased==4){ //Equerda
				P[player].dirInputReleasedTimer[1][0] = P[player].dirInputReleasedTimer[0][0];
				P[player].dirInputReleasedTimer[0][0] = 0;
			}
			if(dirReleased==6){ //Direita
				P[player].dirInputReleasedTimer[1][1] = P[player].dirInputReleasedTimer[0][1];
				P[player].dirInputReleasedTimer[0][1] = 0;
			}
			if(dirReleased==2){ //Baixo
				P[player].dirInputReleasedTimer[1][2] = P[player].dirInputReleasedTimer[0][2];
				P[player].dirInputReleasedTimer[0][2] = 0;
			}
			if(dirReleased==8){ //Cima
				P[player].dirInputReleasedTimer[1][3] = P[player].dirInputReleasedTimer[0][3];
				P[player].dirInputReleasedTimer[0][3] = 0;
			}
		}

		//Incremento do timer de apertar uma direcao
		for (u8 i=0; i < MAX_INPUT_BUFFER; i++){
			if(P[player].dirInputTimer[i] < 200){ P[player].dirInputTimer[i]++; }
		}

		//Incremento do timer de soltar uma direcao
		for (u8 i=0; i < 4; i++){
			if(P[player].dirInputReleasedTimer[0][i] < 200){ P[player].dirInputReleasedTimer[0][i]++; }
			if(P[player].dirInputReleasedTimer[1][i] < 200){ P[player].dirInputReleasedTimer[1][i]++; }
		}

		//Para o comando de carregar para tras
		if ((P[player].direcao==1 && (P[player].key_JOY_LEFT_status==1 || P[player].key_JOY_LEFT_status==2)) || 
			(P[player].direcao==-1 && (P[player].key_JOY_RIGHT_status==1 || P[player].key_JOY_RIGHT_status==2)))
		{
			if (P[player].backChargeTimer == 0) { P[player].perfectDefenseCooldown = P[player].reverseBackChargeTime; }
			if (P[player].backChargeTimer < 100) { P[player].backChargeTimer++; }
			if (P[player].reverseBackChargeTime != 0) { P[player].reverseBackChargeTime = 0; }
			
		} else {
			if (P[player].reverseBackChargeTime == 0) { P[player].lastBackChargeTimer = P[player].backChargeTimer; }
			if (P[player].backChargeTimer != 0) { P[player].backChargeTimer = 0; }
			if (P[player].reverseBackChargeTime < 100) { P[player].reverseBackChargeTime++; }
		}

		//Para o comando de carregar para baixo
		if (P[player].key_JOY_DOWN_status==1 || P[player].key_JOY_DOWN_status==2)
		{
			if (P[player].downChargeTimer < 100) { P[player].downChargeTimer++; }
			if (P[player].reverseDownChargeTime != 0) { P[player].reverseDownChargeTime = 0; }
			
		} else {
			if (P[player].reverseDownChargeTime == 0) { P[player].lastDownChargeTimer = P[player].downChargeTimer; }
			if (P[player].downChargeTimer != 0) { P[player].downChargeTimer = 0; }
			if (P[player].reverseDownChargeTime < 100) { P[player].reverseDownChargeTime++; }
		}

		//---AttackPower & AttackButton
		P[player].attackButton=0;
		
		if(P[player].key_JOY_A_status==1){ P[player].attackPower=WEAK;   P[player].attackButton=BTN_A; }
		if(P[player].key_JOY_B_status==1){ P[player].attackPower=MEDIUM; P[player].attackButton=BTN_B; }
		if(P[player].key_JOY_C_status==1){ P[player].attackPower=FIERCE; P[player].attackButton=BTN_C; }
		if(P[player].key_JOY_X_status==1){ P[player].attackPower=WEAK;   P[player].attackButton=BTN_X; }
		if(P[player].key_JOY_Y_status==1){ P[player].attackPower=MEDIUM; P[player].attackButton=BTN_Y; }
		if(P[player].key_JOY_Z_status==1){ P[player].attackPower=FIERCE; P[player].attackButton=BTN_Z; }

		if(P[player].key_JOY_A_status==1 || P[player].key_JOY_A_status==2){ if(P[player].buttonTimePressed[0]<100){  P[player].buttonTimePressed[0]++; } } else { P[player].buttonTimePressed[0]=0; }
		if(P[player].key_JOY_B_status==1 || P[player].key_JOY_B_status==2){ if(P[player].buttonTimePressed[1]<100){  P[player].buttonTimePressed[1]++; } } else { P[player].buttonTimePressed[1]=0; }
		if(P[player].key_JOY_C_status==1 || P[player].key_JOY_C_status==2){ if(P[player].buttonTimePressed[2]<100){  P[player].buttonTimePressed[2]++; } } else { P[player].buttonTimePressed[2]=0; }
		if(P[player].key_JOY_X_status==1 || P[player].key_JOY_X_status==2){ if(P[player].buttonTimePressed[3]<100){  P[player].buttonTimePressed[3]++; } } else { P[player].buttonTimePressed[3]=0; }
		if(P[player].key_JOY_Y_status==1 || P[player].key_JOY_Y_status==2){ if(P[player].buttonTimePressed[4]<100){  P[player].buttonTimePressed[4]++; } } else { P[player].buttonTimePressed[4]=0; }
		if(P[player].key_JOY_Z_status==1 || P[player].key_JOY_Z_status==2){ if(P[player].buttonTimePressed[5]<100){  P[player].buttonTimePressed[5]++; } } else { P[player].buttonTimePressed[5]=0; }
	}

	if(P[1].key_JOY_START_status==1){ P1_START = TRUE; }
	if(P[2].key_JOY_START_status==1){ P2_START = TRUE; }

	if(gPodeMover==0) //Nao pode se mover
	{
		for (u8 player = 1; player <= 2; player++)
		{
			P[player].attackButton = 0;

			P[player].key_JOY_UP_status    = 0;
			P[player].key_JOY_DOWN_status  = 0;
			P[player].key_JOY_LEFT_status  = 0;
			P[player].key_JOY_RIGHT_status = 0;
			P[player].key_JOY_A_status     = 0;
			P[player].key_JOY_B_status     = 0;
			P[player].key_JOY_C_status     = 0;
			P[player].key_JOY_X_status     = 0;
			P[player].key_JOY_Y_status     = 0;
			P[player].key_JOY_Z_status     = 0;
			P[player].key_JOY_START_status = 0;
			P[player].key_JOY_MODE_status  = 0;
		}
	}

	//---
	if((P[1].key_JOY_MODE_status>=1 && P[1].key_JOY_START_status==1) && gDebug==0) //Ativa o Debug com P1_MODE
	{
		gDebug=1;
		P[1].key_JOY_MODE_status=0;
		P[1].key_JOY_START_status=0;
		SPR_setVisibility(GE[1].sprite, VISIBLE);
		SPR_setVisibility(GE[2].sprite, VISIBLE);
	}
	else if((P[1].key_JOY_MODE_status>=1 && P[1].key_JOY_START_status==1) && gDebug==1) //Desativa o Debug com P1_MODE
	{
		gDebug=0;
		P[1].key_JOY_MODE_status=0;
		P[1].key_JOY_START_status=0;
		//VDP_drawText("                              ", 1, 1);
		//VDP_drawText("                              ", 1, 2);
		//VDP_drawText("                              ", 1, 3);
		SPR_setPosition(Rect1BB1_Q1,-8,-8); SPR_setPosition(Rect1BB1_Q2,-8,-8); SPR_setPosition(Rect1BB1_Q3,-8,-8); SPR_setPosition(Rect1BB1_Q4,-8,-8);
		SPR_setPosition(Rect1HB1_Q1,-8,-8); SPR_setPosition(Rect1HB1_Q2,-8,-8); SPR_setPosition(Rect1HB1_Q3,-8,-8); SPR_setPosition(Rect1HB1_Q4,-8,-8);
		SPR_setPosition(Rect2BB1_Q1,-8,-8); SPR_setPosition(Rect2BB1_Q2,-8,-8); SPR_setPosition(Rect2BB1_Q3,-8,-8); SPR_setPosition(Rect2BB1_Q4,-8,-8);
		SPR_setPosition(Rect2HB1_Q1,-8,-8); SPR_setPosition(Rect2HB1_Q2,-8,-8); SPR_setPosition(Rect2HB1_Q3,-8,-8); SPR_setPosition(Rect2HB1_Q4,-8,-8);
		SPR_setVisibility(GE[1].sprite, HIDDEN);
		SPR_setVisibility(GE[2].sprite, HIDDEN);
	}

	//Sistema de pause simples
	if(attractMode==0 && gRoundState==RS_FIGHT && ((gameMode!=GM_TRAINING && (P1_START || P2_START)) ||
		(gameMode==GM_TRAINING && ((playerControlTraining==1 && P2_START) || (playerControlTraining==2 && P1_START))))
	  )
	{
		if(isPaused == TRUE){ isPaused = FALSE; }else{ isPaused = TRUE; }

		XGM_setPCM(P1_SFX, snd_confirm, sizeof(snd_confirm)); XGM_startPlayPCM(P1_SFX, 1, SOUND_PCM_CH3);
	}
}

void FUNCTION_TRAINING_DUMMY(u8 player)
{
	if((playerControlTraining==1 && player==2) || (playerControlTraining==2 && player==1))
	{
		if(trainingAction!=TM_ACT_CPU && trainingAction!=TM_ACT_HUMAN){
			currentJoyState[player] = 0;
		}
		
		if(trainingAction==TM_ACT_STAND || trainingAction==TM_ACT_CROUCH || trainingAction==TM_ACT_JUMP)
		{
			if(trainingAction==TM_ACT_CROUCH){ currentJoyState[player] |= BUTTON_DOWN; }
			if(trainingAction==TM_ACT_JUMP  ){ currentJoyState[player] |= BUTTON_UP; }
		}

		if((trainingGuard==TM_GRD_ON || (trainingGuard==TM_GRD_1STEP && trainingGuard_1Step_counter>0)) && 
			trainingAction!=TM_ACT_CPU && trainingAction!=TM_ACT_HUMAN)
		{
			u8 enemy = 1;
			if(player==1){ enemy = 2; }

			//Inimigo atacando de perto ou projetil inimigo perto
			bool enemyActiveAttack = FUNCTION_CHECK_ENEMY_IS_ATTACKING(player, enemy);

			if(enemyActiveAttack)
			{
				if(P[enemy].x >= P[player].x){ currentJoyState[player] |= BUTTON_LEFT; }
				else{ currentJoyState[player] |= BUTTON_RIGHT; }

				if(P[enemy].guardFlag==GFT_BlockLow){ currentJoyState[player] |= BUTTON_DOWN; }
			}
		}

		if(trainingAction!=TM_ACT_CPU && trainingAction!=TM_ACT_HUMAN)
		{
			u8 enemy = 1;
			if(player==1){ enemy = 2; }

			if(P[enemy].state==620 && gDistancia>40) //Tenta se aproximar do inimigo se estiver provocando
			{
				currentJoyState[player] = 0;

				if(P[enemy].x >= P[player].x){ currentJoyState[player] |= BUTTON_RIGHT; }
				else{ currentJoyState[player] |= BUTTON_LEFT; }
			}
		}
	}
}

void FUNCTION_SPR_POSITION()
{
	DEBUG_PRINT("funcao spr position");
	//ajusta posicao do sprite
	if(P[1].sprite != NULL)
	{
		if(P[1].direcao== 1){ SPR_setPosition(P[1].sprite, P[1].x-(P[1].w-P[1].axisX)-camPosX, P[1].y-P[1].axisY); }
		if(P[1].direcao==-1){ SPR_setPosition(P[1].sprite, P[1].x- P[1].axisX        -camPosX, P[1].y-P[1].axisY); }
	}
	else{ DEBUG_PRINT("Player 1 sprite is NULL"); }

	if(P[2].sprite != NULL)
	{
		if(P[2].direcao== 1){ SPR_setPosition(P[2].sprite, P[2].x-(P[2].w-P[2].axisX)-camPosX, P[2].y-P[2].axisY); }
		if(P[2].direcao==-1){ SPR_setPosition(P[2].sprite, P[2].x- P[2].axisX        -camPosX, P[2].y-P[2].axisY); }
	}
	else{ DEBUG_PRINT("Player 2 sprite is NULL"); }

	if(GE[22].sprite != NULL)
	{
		if(P[1].direcao== 1){ SPR_setPosition(GE[22].sprite, P[1].x-(P[1].w-P[1].axisX)-camPosX, P[1].y-P[1].axisY); }
		if(P[1].direcao==-1){ SPR_setPosition(GE[22].sprite, P[1].x- P[1].axisX        -camPosX, P[1].y-P[1].axisY); }
	}
	else{ DEBUG_PRINT("Player 1 cabeca sprite is NULL"); }

	if(GE[23].sprite != NULL)
	{
		if(P[2].direcao== 1){ SPR_setPosition(GE[23].sprite, P[2].x-(P[2].w-P[2].axisX)-camPosX, P[2].y-P[2].axisY); }
		if(P[2].direcao==-1){ SPR_setPosition(GE[23].sprite, P[2].x- P[2].axisX        -camPosX, P[2].y-P[2].axisY); }
	}
	else{ DEBUG_PRINT("Player 2  cabeca sprite is NULL"); }
}

void FUNCTION_ANIMATION()
{
	DEBUG_PRINT("funcao animacao");
	
	//CONTROL OF ANIMATION E END ANIMATION
	//A.S.G.S. Anti Sprite Glitch System; (Evita a troca simultanea de sprites dos players)
	P[1].ASG_system = FALSE;
	P[2].ASG_system = FALSE;
	if(gASG_system_activate){
		if (P[1].frameTimeAtual==P[1].frameTimeTotal && P[2].frameTimeAtual==P[2].frameTimeTotal) {
			if (gASG_system==FALSE) {
				P[1].ASG_system = TRUE; gASG_system = TRUE;
			} else {
				P[2].ASG_system = TRUE; gASG_system = FALSE;
			}
		}
	}
	
	for(u8 i=1; i<=2; i++)
	{
		if(P[i].hitPause==0 && P[i].ASG_system==FALSE)
		{
			P[i].ASG_system = TRUE;
			
			if (P[i].animTimeAtual < 4200200200) { P[i].animTimeAtual++; }
			if (P[i].frameTimeAtual < 65000) { P[i].frameTimeAtual++; }
			
			if(P[i].frameTimeAtual>P[i].frameTimeTotal) //hora de trocar o frame!
			{
				P[i].animFrame++;
				if(P[i].animFrame>P[i].animFrameTotal) //hora de trocar ou recarregar a animacao!
				{
					//Verifica se tem reversal no buffer
					if(P[i].allowsReversal==TRUE && P[i].bufferReversal!=0){
						FUNCTION_CHECK_SPECIAL(i, P[i].bufferReversal);
						if(i==1){ P1_messageId = MSG_RS; }else{ P2_messageId = MSG_RS; }
					}
					
					else if(P[i].state==100){ PLAYER_STATE(i,100); }
					else if(P[i].state==200){ PLAYER_STATE(i,200); }
					
					// estes aqui previnem bug, caso o tempo de animacao dos Aereos seja definido errado e o player nao tenha tempo de chegar ao solo...
					else if(P[i].state==300 || P[i].state==310 || P[i].state==320){ PLAYER_STATE(i,100); }
					else if(P[i].state>=301 && P[i].state<=326){ PLAYER_STATE(i,100); }
					else if(P[i].state==330){ PLAYER_STATE(i,100); }
					else if(P[i].state==337){ PLAYER_STATE(i,338); }
					else if(P[i].state==338){ PLAYER_STATE(i,338); }
					else if(P[i].state==339){ PLAYER_STATE(i,330); }
					else if(P[i].state==340){ P[i].cancelDefense=FALSE; PLAYER_STATE(i,339); }
					
					else if(P[i].state==410){ PLAYER_STATE(i,410); } //Andando para tras
					else if(P[i].state==420){ PLAYER_STATE(i,420); } //Andando para frente
					else if(P[i].state==470){ if(P[i].key_JOY_DOWN_status>0){ PLAYER_STATE(i,200); }else{ PLAYER_STATE(i,100); } }
					else if(P[i].state==471){ if(P[i].key_JOY_DOWN_status>0){ PLAYER_STATE(i,601); }else{ PLAYER_STATE(i,100); } } //Recuo
					else if(P[i].state==472){ PLAYER_STATE(i,100); } //Corrida
					else if(P[i].state==473){ if(P[i].key_JOY_DOWN_status>0){ PLAYER_STATE(i,601); }else{ PLAYER_STATE(i,100); } } //Esquiva para tras
					else if(P[i].state==474){ if(P[i].key_JOY_DOWN_status>0){ PLAYER_STATE(i,601); }else{ PLAYER_STATE(i,100); } } //Esquiva para frente
					else if(P[i].state==475){ if(P[i].key_JOY_DOWN_status>0){ PLAYER_STATE(i,601); }else{ PLAYER_STATE(i,100); } } //Esquiva para frente durante a corrida
					
					else if(P[i].state>=101 && P[i].state<=106){ PLAYER_STATE(i,100); }
					else if(P[i].state==107){ PLAYER_STATE(i,108); }
					else if(P[i].state==108){ PLAYER_STATE(i,108); }
					else if(P[i].state==109){ PLAYER_STATE(i,100); }
					else if(P[i].state==110){ P[i].cancelDefense=FALSE; PLAYER_STATE(i,109); }
					else if(P[i].state>=151 && P[i].state<=159){ PLAYER_STATE(i,100); }
					else if(P[i].state>=160 && P[i].state<=169){ PLAYER_STATE(i,100); }
					else if(P[i].state>=170 && P[i].state<=179){ PLAYER_STATE(i,100); }

					else if(P[i].state>=201 && P[i].state<=206){ PLAYER_STATE(i,200); }
					else if(P[i].state==207){ PLAYER_STATE(i,208); }
					else if(P[i].state==208){ PLAYER_STATE(i,208); }
					else if(P[i].state==209){ PLAYER_STATE(i,200); }
					else if(P[i].state==210){ P[i].cancelDefense=FALSE; PLAYER_STATE(i,209); }

					else if(P[i].state>=501 && P[i].state<=510){ PLAYER_STATE(i,100); } //end hurts
					else if(P[i].state>=511 && P[i].state<=513){ PLAYER_STATE(i,200); } //end hurts
					else if(P[i].state>=514 && P[i].state<=550){ PLAYER_STATE(i,100); } //end hurts
					else if(P[i].state==552){ if(P[i].key_JOY_DOWN_status>0){ PLAYER_STATE(i,200); }else{ PLAYER_STATE(i,100); } } //end queda
					else if(P[i].state==570){ if(P[i].energiaBase>0){ PLAYER_STATE(i,552); }else{ PLAYER_STATE(i,570); } } //caido ou morto
					else if(P[i].state==571){ PLAYER_STATE(i,552); }
					else if(P[i].state==601){ PLAYER_STATE(i,200); }
					else if(P[i].state==602){ PLAYER_STATE(i,100); }
					else if(P[i].state==603){ PLAYER_STATE(i,310); }
					else if(P[i].state==604){ PLAYER_STATE(i,300); }
					else if(P[i].state==605){ PLAYER_STATE(i,320); }
					else if(P[i].state==607){ PLAYER_STATE(i,100); } //virando em pe
					else if(P[i].state==608){ PLAYER_STATE(i,200); } //virando abaixado
					else if(P[i].state==606){ PLAYER_STATE(i,100); } //end pulos
					else if(P[i].state==610){ PLAYER_STATE(i,100); } //end Intro
					else if(P[i].state>=611 && P[i].state<=614){ PLAYER_STATE(i,100); } //end WIN Pose
					else if(P[i].state==615){ PLAYER_STATE(i,100); } //end time lose
					else if(P[i].state==616){ PLAYER_STATE(i,100); } //fim da apresentação
					else if(P[i].state>=617 && P[i].state<=649){ PLAYER_STATE(i,100); }
					else if(P[i].state==650){ PLAYER_STATE(i,100); } //end estado especifico
					else if(P[i].state==660){ PLAYER_STATE(i,100); } //end ataques especiais
					
					else if(P[i].state>=700 && P[i].state<=899){ PLAYER_STATE(i,100); } //end magias
					else if(P[i].state>=800 && P[i].state<=899){ PLAYER_STATE(i,100); } //end supers
					
					else if(P[i].state==900){ PLAYER_STATE(i,153); } //errou arremesso
					else if(P[i].state==930){ PLAYER_STATE(i,100); } //fim do arremesso
					else if(P[i].state==920){ PLAYER_STATE(i,926); } //errou arremesso
					else if(P[i].state==931){ PLAYER_STATE(i,100); } //fim do arremesso
					else if(P[i].state==932){ PLAYER_STATE(i,100); } //fim do arremesso
					else if(P[i].state==926){ PLAYER_STATE(i,100); } //fim do movimento
					else if(P[i].state==901){ PLAYER_STATE(i,153); } //errou arremesso
					else if(P[i].state==950){ PLAYER_STATE(i,100); }
					else if(P[i].state==973){ PLAYER_STATE(i,100); }
					else if(P[i].state==975){ PLAYER_STATE(i,100); }
					else if(P[i].state>=980 && P[i].state<=999){ PLAYER_STATE(i,100); }
				}

				P[i].frameTimeAtual = 1;
				P[i].frameTimeTotal = P[i].dataAnim[P[i].animFrame];

				//hpig 1.1 anti glitch animation overflow
				if(P[i].sprite != NULL)
				{
					u16 totalReal = P[i].sprite->animation->numFrame;
					if( (P[i].animFrame-1) < totalReal)
					{ 
						SPR_setAnimAndFrame(P[i].sprite, P[i].animRow, P[i].animFrame-1); //set the animation if is OK

						if(GE[21 + i].sprite != NULL){
							SPR_setAnimAndFrame(GE[21 + i].sprite,  P[i].animRow, P[i].animFrame-1);
						}else{
							if(i==1){ DEBUG_PRINT("Player 1 cabeca sprite is NULL"); }
							else if(i==2){ DEBUG_PRINT("Player 2 cabeca sprite is NULL"); }
						}

						FUNCTION_DEPTH(i);
					}
				}else{
					if(i==1){ DEBUG_PRINT("Player 1 sprite is NULL"); }
					else if(i==2){ DEBUG_PRINT("Player 2 sprite is NULL"); }
				}

				FUNCTION_FSM_HITBOXES(i); //Atualiza as Hurt / Hitboxes
			}
		}
	}
	FUNCTION_SPR_POSITION(); //Define a posicao do Sprite
}

void FUNCTION_DEPTH(u8 Player)
{
	DEBUG_PRINT("funcao depth");
	
	//Qto menor o 'depth', mais para frente o objeto fica na tela
	P[Player].depth = Player*2+20;
		 if(P[Player].state>=500 && P[Player].state<=582)                         {P[Player].depth  = Player*2+40;} //Hurts, Caindo
	else if(P[Player].state==100)                                                 {P[Player].depth  = Player*2+20;} //Parado
	else if(P[Player].state==410 || P[Player].state==420)                         {P[Player].depth  = Player*2+20;} //Andando
	else if(P[Player].state==471 || P[Player].state==472)                         {P[Player].depth  = Player*2+15;} //Rolamento, Dash, Esquiva
	else if(P[Player].state>=107 && P[Player].state<=110)                         {P[Player].depth  = Player*2+20;} //Defesa em Pe
	else if(P[Player].state>=207 && P[Player].state<=210)                         {P[Player].depth  = Player*2+20;} //Defesa Abaixado
	else if(P[Player].state>=337 && P[Player].state<=340)                         {P[Player].depth  = Player*2+20;} //Defesa no Ar
	else if(P[Player].state>=101 && P[Player].state<=159)                         {P[Player].depth  = Player*2+10;} //Golpes em Pe
	else if(P[Player].state>=160 && P[Player].state<=169)                         {P[Player].depth  = Player*2+10;} //Golpes em Pe
	else if(P[Player].state>=170 && P[Player].state<=179)                         {P[Player].depth  = Player*2+10;} //Golpes de comando
	else if(P[Player].state>=200 && P[Player].state<=206)                         {P[Player].depth  = Player*2+10;} //Golpes Abaixados
	else if(P[Player].state==300 || P[Player].state==310 || P[Player].state==320) {P[Player].depth  = Player*2+20;} //Pulos
	else if(P[Player].state>=301 && P[Player].state<=326)                         {P[Player].depth  = Player*2+10;} //Golpes Aereos
	else if(P[Player].state>=611 && P[Player].state<=614)                         {P[Player].depth  = Player*2+255;} //Vitoria
	else if(P[Player].state>=700 && P[Player].state<=899)                         {P[Player].depth  = Player*2+10;} //Magias
	else if(P[Player].state>=900 && P[Player].state<=969)                         {P[Player].depth  = Player*2+11;} //arremesso
	else if(P[Player].state>=970 && P[Player].state<=989)                         {P[Player].depth  = Player*2+11;} //arremesso
	else if(P[Player].state>=990 && P[Player].state<=999)                         {P[Player].depth  = Player*2+ 5;} //arremesso

	//Estados de contra-ataque
	// if(((P[Player].id==ID_KRAUSER || P[Player].id==ID_OMEGA_KRAUSER) && P[Player].state==750) ||
	// 	(P[Player].id==ID_GEESE && (P[Player].state==710 || P[Player].state==711 || P[Player].state==712)) ||
	// 	((P[Player].id==ID_BLUE_MARY || P[Player].id==ID_BLUE_MARY_EX) && (P[Player].state==750 || P[Player].state==755))
	//   )
	// {
	// 	P[Player].depth = Player*2+25;
	// }
	
	//Define o Depth, SE e SOMENTE SE o sprite estiver carregado. 
	//O comando 'SPR_setDepth' pode ser potencialmente perigoso e TRAVAR o jogo se o SPRITE nao estiver completamente carregado na VRAM
	if(P[Player].sprite != NULL){ SPR_setDepth(P[Player].sprite, P[Player].depth); }
	if(GE[21 + Player].sprite != NULL){ SPR_setDepth(GE[21 + Player].sprite, P[Player].depth -1); } //Cabeças do Chonrei e do Chonshu
}

