	// 	}

	// 	if(camPosY < -32){
	// 		camPosY = -32;
	// 	}
	// 	if(camPosY > 0){
	// 		camPosY = 0;
	// 	}
	// }

	// if(camPosYanterior != camPosY){
	// 	VDP_setVerticalScrollVSync(BG_B, camPosY+32);
	// 	VDP_setVerticalScrollVSync(BG_A, camPosY+32);
	// 	camPosYanterior = camPosY;
	// }

