	DEBUG_PRINT("funcao clear vdp");	
	gInd_tileset=0;

	if(Rect1BB1_Q1){ SPR_releaseSprite(Rect1BB1_Q1); Rect1BB1_Q1 = NULL; } if(Rect1BB1_Q2){ SPR_releaseSprite(Rect1BB1_Q2); Rect1BB1_Q2 = NULL; }
