	if(Rect1HB1_Q1){ SPR_releaseSprite(Rect1HB1_Q1); Rect1HB1_Q1 = NULL; } if(Rect1HB1_Q2){ SPR_releaseSprite(Rect1HB1_Q2); Rect1HB1_Q2 = NULL; }
