void FUNCTION_APPLY_FLIP(u8 player, bool hFlip)
{
	// if(P[player].isToHFlip != hFlip)
	// {
	// 	u8 axisX = P[player].axisX - ((P[player].w)/2);
	// 	P[player].axisX = ((P[player].w)/2) + (axisX *-1);

	// 	P[player].isToHFlip = hFlip;
	// }

	if(hFlip==TRUE)
	{
		//Ajustando o eixo X
		u8 axisX = P[player].axisX - ((P[player].w)/2);
		P[player].axisX = ((P[player].w)/2) + (axisX *-1);
	}

	if(P[player].sprite != NULL)
	{
		//if(P[player].isToHFlip==FALSE){}
		if(hFlip==FALSE){
			if(P[player].direcao==1){ SPR_setHFlip(P[player].sprite, FALSE); }else{ SPR_setHFlip(P[player].sprite, TRUE); }
		}else{
			if(P[player].direcao==1){ SPR_setHFlip(P[player].sprite, TRUE); }else{ SPR_setHFlip(P[player].sprite, FALSE); }
		}
	}

	// Cabeças do Chonrei e do Chonshu
	if(GE[22 + player].sprite != NULL)
	{
		//if(P[player].isToHFlip==FALSE){}
		if(hFlip==FALSE){
			if(P[player].direcao==1){ SPR_setHFlip(GE[22 + player].sprite, FALSE); }else{ SPR_setHFlip(GE[22 + player].sprite, TRUE); }
		}else{
			if(P[player].direcao==1){ SPR_setHFlip(GE[22 + player].sprite, TRUE); }else{ SPR_setHFlip(GE[22 + player].sprite, FALSE); }
		}
	}
}

void flipHTilemap(TileMap *map, u16 altura, u16 largura, u16 index, u16 pos_x, u16 pos_y, VDPPlane plane, u8 pal)
{
	for(u16 i = 0; i < largura; i++)
	{
		VDP_setTileMapEx(plane,map,TILE_ATTR_FULL(pal,FALSE,FALSE,TRUE,index), pos_x + i, pos_y, largura-i- 1, 0, 1, altura, DMA_QUEUE);
	}
}

