void PHYSICS_RUGAL(u8 i) 
{
	// soco do rugal
	if(P[i].state==102 && P[i].hitPause==0 && P[i].animFrame== 8 && P[i].frameTimeAtual==1)
	{
		P[i].hSpeed=35;
		P[i].x += P[i].hSpeed*(P[i].direcao);
	}
	
	// Andando para frente
	if(P[i].state==420 && P[i].hitPause==0)
	{
		if(gPing2==0){ P[i].hSpeed=2; }else{ P[i].hSpeed=3; }
		P[i].x += P[i].hSpeed*(P[i].direcao);
	}
	
	// Andando para trás
	if(P[i].state==410 && P[i].hitPause==0)
	{
		P[i].hSpeed=3;
		P[i].x += P[i].hSpeed*(P[i].direcao*-1);
	}

	//Corrida
	if((P[i].state==472) && P[i].hitPause==0)
	{
		P[i].hSpeed=6;
		P[i].x+=P[i].hSpeed*P[i].direcao;
	}

	//Recuo
	if((P[i].state==471) && P[i].hitPause==0)
	{
		P[i].gravidadeY = 0;
		P[i].impulsoY = 0;

			 if(P[i].animFrame==1){  P[i].hSpeed=0; P[i].x-=P[i].hSpeed*P[i].direcao; }
		else if(P[i].animFrame==2){  P[i].hSpeed=7; P[i].x-=P[i].hSpeed*P[i].direcao; }
		else if(P[i].animFrame==3){  P[i].hSpeed=1; P[i].x-=P[i].hSpeed*P[i].direcao; }
		
		if(P[i].y>gAlturaPiso)
		{
			P[i].y=gAlturaPiso;
			P[i].gravidadeY = 0;
			P[i].impulsoY = 0;
			
			PLAYER_STATE(i,100);
		}
	}

	if(P[i].state==473  && P[i].hitPause==0)// rolamento para tras
	{
		//controle manual
		if(P[i].animFrame== 3){  P[i].hSpeed=6; P[i].x-=P[i].hSpeed*P[i].direcao;}
		if(P[i].animFrame== 4){  P[i].hSpeed=5; P[i].x-=P[i].hSpeed*P[i].direcao;}
		if(P[i].animFrame== 5){  P[i].hSpeed=0; P[i].x-=P[i].hSpeed*P[i].direcao;}
		if(P[i].animFrame== 6){  P[i].hSpeed=0; P[i].x-=P[i].hSpeed*P[i].direcao;}
	}

	if(P[i].state==474  && P[i].hitPause==0)// rolamento para frente
	{
		//controle manual
		if(P[i].animFrame== 3){  P[i].hSpeed=5; P[i].x+=P[i].hSpeed*P[i].direcao;}
		if(P[i].animFrame== 4){  P[i].hSpeed=5; P[i].x+=P[i].hSpeed*P[i].direcao;}
		if(P[i].animFrame== 5){  P[i].hSpeed=0; P[i].x+=P[i].hSpeed*P[i].direcao;}
		if(P[i].animFrame== 6){  P[i].hSpeed=0; P[i].x+=P[i].hSpeed*P[i].direcao;}
	}

	if(P[i].state==475  && P[i].hitPause==0)// rolamento para frente durante a corrida
	{
		//controle manual
		if(P[i].animFrame== 3){  P[i].hSpeed=7; P[i].x+=P[i].hSpeed*P[i].direcao;}
		if(P[i].animFrame== 4){  P[i].hSpeed=7; P[i].x+=P[i].hSpeed*P[i].direcao;}
		if(P[i].animFrame== 5){  P[i].hSpeed=0; P[i].x+=P[i].hSpeed*P[i].direcao;}
		if(P[i].animFrame== 6){  P[i].hSpeed=0; P[i].x+=P[i].hSpeed*P[i].direcao;}
	}

	if(P[i].state==710 && P[i].hitPause==0)//genocide cutter
	{
		//Anula a gravidade, para controle manual
		P[i].gravidadeY = 0;
		P[i].impulsoY = 0;
		
		
		//controle manual
		
		
		if(P[i].animFrame== 6){ P[i].y-=6; }
		if(P[i].animFrame== 7){ P[i].y-=5; }
		if(P[i].animFrame== 8){ P[i].y-=5; }
		if(P[i].animFrame== 9){ P[i].y-=4; }
		if(P[i].animFrame== 10){ P[i].y-=2; }
		if(P[i].animFrame== 11){ P[i].y+=1; }
		if(P[i].animFrame== 12){ P[i].y+=3; }
		if(P[i].animFrame== 13){ P[i].y+=4; }

		//finaliza
		if(P[i].y>gAlturaPiso)
		{
			P[i].y=gAlturaPiso;
			P[i].gravidadeY = 0;
			P[i].impulsoY = 0;
			PLAYER_STATE(i,660);
		}
	}

	if(P[i].state==725 && P[i].hitPause==0)//vanishing rush
	{
		if(P[i].animFrame>=18 && P[i].animFrame<=22) //some
		{
			if(P[i].sprite){ SPR_setVisibility(P[i].sprite, HIDDEN); }
			P[i].hSpeed = 13;
			P[i].x += P[i].hSpeed*P[i].direcao;
		}

		if(P[i].animFrame==23 ) //aparece
		{
			if(P[i].sprite){ SPR_setVisibility(P[i].sprite, VISIBLE); }
		}
	}

	//'700' Repuken
	if(P[i].state==700 && P[i].animFrame==6 && P[i].frameTimeAtual==1 &&
		((P[i].hitPause==0 && superPause==FALSE) || (P[i].hitPause!=0 && superPause==TRUE)))
	{
		FUNCTION_CREATE_PROJECTILE(i, P[i].id, 1, 0);
	}

	//713 - Kaiser Wave
	if((P[i].state==713 && P[i].animFrame==10 && P[i].frameTimeAtual==1) &&
		((P[i].hitPause==0 && superPause==FALSE) || (P[i].hitPause!=0 && superPause==TRUE)))
	{
		FUNCTION_CREATE_PROJECTILE(i, P[i].id, 2, 1);
	}

	//713 - Kaiser Wave - atualizando a posicao da magia
	if(P[i].fBall[1].active==TRUE && P[i].fBall[1].projectId==2)
	{
		//Atualiza a posicao da magia
		s16 posX = P[i].fBall[1].x - P[i].fBall[1].axisX;
		s16 posY = P[i].fBall[1].y - P[i].fBall[1].axisY;

		s16 posY2 = posY + 64;

		SPR_setPosition(P[i].fBall[1].spriteFBall, posX-camPosX, posY-camPosY);
		if(i==1){ SPR_setPosition(GE[9].sprite, posX-camPosX, posY2-camPosY); }
		if(i==2){ SPR_setPosition(GE[11].sprite, posX-camPosX, posY2-camPosY); }
	}

	//713 - Kaiser Wave - limpando o sprite extra da magia
	if(P[i].fBall[1].active==FALSE)
	{
		if(i==1){ if(GE[9].sprite != NULL){ SPR_releaseSprite(GE[9].sprite); GE[9].sprite = NULL; } }
		if(i==2){ if(GE[11].sprite != NULL){ SPR_releaseSprite(GE[11].sprite); GE[11].sprite = NULL; } }
	}
}

