void ROOM_TELA_DISCLAIMER()
{
	bool running = TRUE;
	gFrames = 0;

	u8 posX1, posX2, posX3, posX4, posX5, posX6, posX7;

	while(running) /// LOOP ///
    {
		gFrames++;

		FUNCTION_UTIL();
		FUNCTION_INPUT_SYSTEM(); //Verifica os joysticks 
		
		//inicializacao
		if(gFrames==1)
		{
			gPodeMover = 1;
			gInd_tileset = 1;
			
			VDP_setBackgroundColor(0);

			// VDP_drawImageEx(BG_B, &room_0_bgb, TILE_ATTR_FULL(PAL0, FALSE, FALSE, FALSE, gInd_tileset), 0, 0, FALSE, TRUE);
			// gInd_tileset += room_0_bgb.tileset->numTile;
			// PAL_setPalette(PAL0, room_0_bgb.palette->data, DMA);

			VDP_loadFont(&tile_font_option, DMA);
			PAL_setPalette(PAL1, pal_font_option.data, DMA);

			posX1 = 40-15;
			posX2 = 40-3;
			posX3 = 40-3;
			posX4 = 40-3;
			posX5 = 40-3;
			posX6 = 40-3;
			posX7 = 40-3;
		}

		if(gFrames>=2)
		{
			
			VDP_drawText("DISCLAIMER                              ", 15 + posX1, 2);
			VDP_drawText("GAME CREATED WITH EDUCATIONAL AND       ", 3 + posX2, 6);
			VDP_drawText("LEARNING OBJECTIVE.                     ", 3 + posX3, 7);
			VDP_drawText("PLEASE DO NOT SELL THIS ROM.            ", 3 + posX4, 9);
			VDP_drawText("NOT PRODUCED BY OR UNDER LICENSA        ", 3 + posX5, 11);
			VDP_drawText("FROM SEGA.                              ", 3 + posX6, 12);
			VDP_drawText("MADE WITH HAMOOPIG AND SGDK.            ", 3 + posX7, 14);
			
			if(gPing2 == 0){
				if(gFrames>2 && posX1>0){ posX1--; }
				if(gFrames>30 && posX2>0){ posX2--; }
				if(gFrames>60 && posX3>0){ posX3--; }
				if(gFrames>90 && posX4>0){ posX4--; }
				if(gFrames>120 && posX5>0){ posX5--; }
				if(gFrames>150 && posX6>0){ posX6--; }
				if(gFrames>180 && posX7>0){ posX7--; }
			}
		}

		if((gFrames>=60*10) || ((P[1].key_JOY_START_status==1 || P[2].key_JOY_START_status==1) && gFrames>10))
		{
			PAL_fadeOut(0, 63, FADE_TIME, FALSE);
			CLEAR_VDP();

			gRoom=R_TELA_MEGA;
			gFrames=0;

			running = FALSE;
		}

		//Atualizacao
        SPR_update();
        SYS_doVBlankProcess(); //Wait for screen refresh and do all SGDK VBlank tasks
	}
}

void ROOM_TELA_MEGA()
{
	kprintf("Room Tela Mega");

	bool running = TRUE;
	gFrames = 0;

	u8 posX;

	while(running) /// LOOP ///
    {
		gFrames++;

		FUNCTION_UTIL();
		FUNCTION_INPUT_SYSTEM(); //Verifica os joysticks 
		
		//inicializacao
		if(gFrames==1)
		{
			gPodeMover = 1;
			gInd_tileset = 1;

			VDP_loadTileSet(bg_mega_bga.tileset,gInd_tileset,DMA);
			VDP_setTileMapEx(BG_A,bg_mega_bga.tilemap,TILE_ATTR_FULL(PAL2,0,FALSE,FALSE,gInd_tileset),0,0,0,0,40,28,DMA_QUEUE);
			PAL_setPalette(PAL2, bg_mega_bga.palette->data, DMA);
			gInd_tileset += bg_mega_bga.tileset->numTile;
			
			VDP_loadFont(&tile_font_option, DMA);
			PAL_setPalette(PAL1, pal_font_option.data, DMA);

			VDP_setBackgroundColor(0);

			posX = 13;
		}

		if((gFrames>=60*5) || ((P[1].key_JOY_START_status==1 || P[2].key_JOY_START_status==1) && gFrames>10))
		{
			PAL_fadeOut(0, 63, FADE_TIME, FALSE);
			CLEAR_VDP();

			gRoom=R_TELA_CREDITOS;
			gFrames=0;

			running = FALSE;
		}

		//Atualizacao
        SPR_update();
        SYS_doVBlankProcess(); //Wait for screen refresh and do all SGDK VBlank tasks
	}
}

