void ROOM_DESCOMPRESSION()
{
	kprintf("Room Descompression");

	bool running = TRUE;
	gFrames = 0;

	while(running) /// LOOP ///
    {
		gFrames++;

		GE[1].sprite = SPR_addSpriteExSafe(&spr_point,  0, 225, TILE_ATTR(PAL3, FALSE, FALSE, FALSE), SPR_FLAG_AUTO_VISIBILITY | SPR_FLAG_AUTO_VRAM_ALLOC | SPR_FLAG_AUTO_TILE_UPLOAD );
		GE[2].sprite = SPR_addSpriteExSafe(&spr_point,  0, 225, TILE_ATTR(PAL3, FALSE, FALSE, FALSE), SPR_FLAG_AUTO_VISIBILITY | SPR_FLAG_AUTO_VRAM_ALLOC | SPR_FLAG_AUTO_TILE_UPLOAD );
		GE[3].sprite = SPR_addSpriteExSafe(&spr_point,  0, 225, TILE_ATTR(PAL3, FALSE, FALSE, FALSE), SPR_FLAG_AUTO_VISIBILITY | SPR_FLAG_AUTO_VRAM_ALLOC | SPR_FLAG_AUTO_TILE_UPLOAD );
		
		if(gFrames==20)
		{
			if (GE[1].sprite){ SPR_releaseSprite(GE[1].sprite); GE[1].sprite = NULL; }
			if (GE[2].sprite){ SPR_releaseSprite(GE[2].sprite); GE[2].sprite = NULL; }
			if (GE[3].sprite){ SPR_releaseSprite(GE[3].sprite); GE[3].sprite = NULL; }

			gRoom=gDescompressionExit;
			gFrames=0;

			CLEAR_VDP();
			SPR_initEx(VRAM_SIZE); // reinicia a area de sprites

			running = FALSE;
		}

		//Atualizacao
        SPR_update();
        SYS_doVBlankProcess(); //Wait for screen refresh and do all SGDK VBlank tasks
	}
}

void ROOM_IN_GAME()
{
	kprintf("Room In Game");

	bool running = TRUE;
	gFrames = 0;
	
	while(running) /// LOOP ///
    {
		
		//código para palete swap
		// if(gBG_Choice==CENARIO_RING)
		// 	{ 
				
				
		// 		if(troca_paleta == 1){PAL_setPalette(PAL0, bga_ring_pal2.data, DMA);}
		// 		else if (troca_paleta == 2){PAL_setPalette(PAL0, bga_ring_pal3.data, DMA);}
		// 		else if (troca_paleta == 3){PAL_setPalette(PAL0, bga_ring_pal2.data, DMA);}
		// 		else if (troca_paleta == 0){PAL_setPalette(PAL0, ring_bga.palette->data, DMA);}
				
		// 	}
		
		
		//end palete swap
		// kprintf("estadop1 = %d", P[1].state);
		// kprintf("estadop2 = %d", P[2].state);
		// kprintf("paleta_atual = %d", troca_paleta);
		// kprintf("gping10 = %d", gPing10);
		gFrames++;

		FUNCTION_UTIL();
		FUNCTION_INPUT_SYSTEM(); //Verifica os joysticks 

		//codigo de "SLOW MOTION KO"
		
		if((P[1].energiaBase==0 || P[2].energiaBase==0) && gFrames>100)
		{
			gPauseSystem=1;
			gPauseKoTimer++;
			if(gPauseKoTimer>=30 && gPauseKoTimer<=160)
			{
				if(gPing2==0){gPauseSystem=0;}
				if(gPing2==1){gPauseSystem=1;}
			}
			if(gPauseKoTimer>160)
			{
				gPauseSystem=0;
			}
		}	
		
		
		if(gFrames==1){  //Inicializacao
			gPodeMover=0;
			FUNCTION_INITIALIZATION();
		}
		if(gFrames<=framesIntro+246){
			FUNCTION_ROUND_INIT(); //Rotina de Letreiramento de inicio dos rounds
		}else{
			if(TREINO)
			{
				if( (playerControlTraining==1 && P[1].key_JOY_START_status==1) ||
					(playerControlTraining==2 && P[2].key_JOY_START_status==1))
				{
					gRoom = R_DESCOMPRESSION;
					gDescompressionExit = R_TRAINING_MENU;
					gFrames = 0;
				}
			}
		}
		
		if(gPauseSystem==0 && isPaused==FALSE)
		{
			FUNCTION_UPDATE_SPARKS();  //Atualiza os sparks
			FUNCTION_ANIMATION();    //Atualiza animacao
			FUNCTION_FSM();          //FSM = Finite State Machine (Maquina de Estados)
			FUNCTION_PHYSICS();      //Funcoes de Fisica
			FUNCTION_CAMERA();       //Atualiza a camera

			if(gFrames>framesIntro+246){ FUNCTION_HUD(); }

			if(superPause==FALSE){ CEN_Anima(gBG_Choice, gPing10); }

			if(gDebug){ FUNCTION_DEBUG(); } //Debug
		}

		if(gRoom != R_IN_GAME){
			PAL_fadeOut(0, 63, FADE_TIME, FALSE);
			CLEAR_VDP();
			running = FALSE;
		}

		//Atualizacao
        if(gPauseSystem==0 && isPaused==FALSE){ SPR_update(); }
        SYS_doVBlankProcess(); //Wait for screen refresh and do all SGDK VBlank tasks
	}
}

void ROOM_AFTER_MATCH()
{
	kprintf("Room After Match");

	bool running = TRUE;
	gFrames = 0;

	while(running) /// LOOP ///
    {
		gFrames++;

		FUNCTION_UTIL();
		FUNCTION_INPUT_SYSTEM(); //Verifica os joysticks

		if(gFrames==1)
		{
			gPodeMover = 1;
			gContinueOption = 1;
			gInd_tileset = 1;
			gScrollValue = 0;

			VDP_loadFont(&tile_font, DMA_QUEUE);
			PAL_setPalette(PAL2, pal_font.data, DMA);
			VDP_setHorizontalScroll(BG_B, gScrollValue);
			VDP_setVerticalScroll(BG_B, gScrollValue);

			VDP_loadTileSet(bg_win_bgb.tileset,gInd_tileset,DMA); 
			VDP_setTileMapEx(BG_B,bg_win_bgb.tilemap,TILE_ATTR_FULL(PAL1,0,FALSE,FALSE,gInd_tileset),0,0,0,0,40,28,DMA_QUEUE); //33 é a altura do cenario com as palavras de final
			PAL_setPalette(PAL1, bg_win_bgb.palette->data, DMA);
			gInd_tileset += bg_win_bgb.tileset->numTile;
		}
		
		if(gFrames==2)
		{
			//WINNER
			if(gWinnerID==ID_RYO)
			{
				VDP_loadTileSet(bg_win_ryo_bga.tileset,gInd_tileset,DMA); 
				VDP_setTileMapEx(BG_A,bg_win_ryo_bga.tilemap,TILE_ATTR_FULL(PAL0,0,FALSE,FALSE,gInd_tileset),0,0,0,0,40,28,DMA_QUEUE);
				PAL_setPalette(PAL0, bg_win_ryo_bga.palette->data, DMA);
				gInd_tileset += bg_win_ryo_bga.tileset->numTile;
				
				//----------------------------------------------------------------------------------------------------------------------------------
				//METODO COM Fonte
				if(gLoseID==ID_RYO)
				{	
					VDP_drawTextEx(BG_A, "QUEM EH",TILE_ATTR(PAL2, TRUE, FALSE, FALSE), 6,6, DMA_QUEUE);
					VDP_drawTextEx(BG_A,"ESSE", TILE_ATTR(PAL2, TRUE, FALSE, FALSE),6,7, DMA_QUEUE);
					VDP_drawTextEx(BG_A,"MACACO",TILE_ATTR(PAL2, TRUE, FALSE, FALSE), 6,8, DMA_QUEUE);
					VDP_drawTextEx(BG_A,"DE",TILE_ATTR(PAL2, TRUE, FALSE, FALSE), 6,9, DMA_QUEUE);
					VDP_drawTextEx(BG_A,"IMITACAO",TILE_ATTR(PAL2, TRUE, FALSE, FALSE), 6,10, DMA_QUEUE);
				}else if(gLoseID==ID_RUGAL){ 
					VDP_drawTextEx(BG_A, "QUEM EH A",TILE_ATTR(PAL2, TRUE, FALSE, FALSE), 5,3, DMA_QUEUE);
					VDP_drawTextEx(BG_A,"RAPUNZEL", TILE_ATTR(PAL2, TRUE, FALSE, FALSE),5,4, DMA_QUEUE);
					VDP_drawTextEx(BG_A,"AGORA?",TILE_ATTR(PAL2, TRUE, FALSE, FALSE), 5,5, DMA_QUEUE);
					VDP_drawTextEx(BG_A,"HEIN",TILE_ATTR(PAL2, TRUE, FALSE, FALSE), 5,6, DMA_QUEUE);
					VDP_drawTextEx(BG_A,"MARY?",TILE_ATTR(PAL2, TRUE, FALSE, FALSE), 5,7, DMA_QUEUE);
				}
				//----------------------------------------------------------------------------------------------------------------------------------
			}
			else if(gWinnerID==ID_RUGAL)	
			{
				VDP_loadTileSet(bg_win_rugal_bga.tileset,gInd_tileset,DMA); 
				VDP_setTileMapEx(BG_A,bg_win_rugal_bga.tilemap,TILE_ATTR_FULL(PAL0,0,FALSE,FALSE,gInd_tileset),0,0,0,0,40,28,DMA_QUEUE);
				PAL_setPalette(PAL0, bg_win_rugal_bga.palette->data, DMA);
				gInd_tileset += bg_win_rugal_bga.tileset->numTile;
				//----------------------------------------------------------------------------------------------------------------------------------
				//METODO COM TILES
				//numeros: local destino X, local destino Y, Inicio do Recorte X, Inicio do Recorte Y, Tamanho do Recorte X, Tamanho do Recorte Y
				//todas as medidas em tiles! 1 tile = 8px
				//observe tambem que primeiro eu carrego o BG_B, depois o BG_A
				if(gLoseID==ID_RYO)
				{
					VDP_drawTextEx(BG_A, "SEU",TILE_ATTR(PAL2, TRUE, FALSE, FALSE), 2,6, DMA_QUEUE);
					VDP_drawTextEx(BG_A,"RECALQUE", TILE_ATTR(PAL2, TRUE, FALSE, FALSE),2,7, DMA_QUEUE);
					VDP_drawTextEx(BG_A,"BATE NAS",TILE_ATTR(PAL2, TRUE, FALSE, FALSE), 2,8, DMA_QUEUE);
					VDP_drawTextEx(BG_A,"MINHAS",TILE_ATTR(PAL2, TRUE, FALSE, FALSE), 2,9, DMA_QUEUE);
					VDP_drawTextEx(BG_A,"16 CORES",TILE_ATTR(PAL2, TRUE, FALSE, FALSE), 2,10, DMA_QUEUE);
					VDP_drawTextEx(BG_A,"E VOLTA...",TILE_ATTR(PAL2, TRUE, FALSE, FALSE), 2,11, DMA_QUEUE);
				}else if(gLoseID==ID_RUGAL){
					VDP_drawTextEx(BG_A, "LINDA",TILE_ATTR(PAL2, TRUE, FALSE, FALSE), 3,5, DMA_QUEUE);
					VDP_drawTextEx(BG_A,"DE SE", TILE_ATTR(PAL2, TRUE, FALSE, FALSE),3,6, DMA_QUEUE);
					VDP_drawTextEx(BG_A,"VER! ^",TILE_ATTR(PAL2, TRUE, FALSE, FALSE), 3,7, DMA_QUEUE);
					VDP_drawTextEx(BG_A,"DIFICIL",TILE_ATTR(PAL2, TRUE, FALSE, FALSE), 3,8, DMA_QUEUE);
					VDP_drawTextEx(BG_A,"DE",TILE_ATTR(PAL2, TRUE, FALSE, FALSE), 3,9, DMA_QUEUE);
					VDP_drawTextEx(BG_A,"VENCER",TILE_ATTR(PAL2, TRUE, FALSE, FALSE), 3,10, DMA_QUEUE);
				}
				//----------------------------------------------------------------------------------------------------------------------------------
			}
		}

		if((P[1].key_JOY_START_status==1 || P[2].key_JOY_START_status==1) && gFrames>=5)
		{
			//Modo arcade
			if(gameMode == GM_ARCADE && P[2].active_AI == TRUE)
			{
				if(fase < faseMAX){ fase++; }

				P[2].id = characterFase[fase];

				krauserUp += 1;

				gRoom=R_DESCOMPRESSION;
				
				//Acessando o final verdadeiro
				if(krauserUp==MAX_FASES)
				{
					if (P[1].id==ID_RYO) { gRoom=R_FINAL_RYO; }
					if (P[1].id==ID_RUGAL){ gRoom=R_FINAL_RUGAL; }
				}
				
				gDescompressionExit=R_IN_GAME;
			}
			else
			{
				gRoom = R_TELA_APRESENTACAO;
			}

			gFrames = 0;

			PAL_fadeOut(0, 63, FADE_TIME, FALSE);
			CLEAR_VDP();

			running = FALSE;
		}
		
		//Atualizacao
        SPR_update();
        SYS_doVBlankProcess(); //Wait for screen refresh and do all SGDK VBlank tasks
	}
}

// inicio tela de versus
void ROOM_TELA_VERSUS()//TELA DE VERSUS -------------------------------------------------------------------
{
	kprintf("Room Versus");

	VDP_setScrollingMode(HSCROLL_PLANE, VSCROLL_COLUMN);
	gScrollValues[0] = 32;
	gScrollValues[15] = 224;
	memsetU16(&gScrollValues[1], 32, 4);	//valor da posição incial player 1
	memsetU16(&gScrollValues[16], 224, 4);  //valor da posição incial player 2
	gScrollValue = 0;

	s16 bga_initial_scroll[20]={0};
	VDP_setVerticalScrollTile(BG_B, 0, gScrollValues, 20, DMA_QUEUE);
	VDP_setVerticalScrollTile(BG_A, 0, bga_initial_scroll, 20, DMA_QUEUE);
	VDP_setHorizontalScroll(BG_A, 0);
	VDP_setHorizontalScroll(BG_B, 0);
	gFrames = 1;
	
	while(gRoom == R_TELA_VERSUS)
	{
		SYS_doVBlankProcess();
		gFrames++;
		
		if(gFrames==285 || (gFrames>5 && (P[1].key_JOY_START_status==1 || P[2].key_JOY_START_status==1)))
		{
			PAL_fadeOut(0, 63, FADE_TIME, FALSE);

			CLEAR_VDP();
			VDP_setScrollingMode(HSCROLL_PLANE, VSCROLL_PLANE);

			gRoom = R_DESCOMPRESSION;
			gDescompressionExit = R_IN_GAME;
		}
	}
}
