void ROOM_TELA_GAME_OVER()
{
	bool running = TRUE;
	gFrames = 0;

	u32 VelocidadeTransicao = 360;

	while(running) /// LOOP ///
    {
		gFrames++;

		FUNCTION_UTIL();
		FUNCTION_INPUT_SYSTEM(); //Verifica os joysticks 
		
		// ETAPA 1 -------------------------------------------------------------------------------------------------------
		
		//inicializacao
		if(gFrames==1)
		{
			gPodeMover=1;
			gInd_tileset=1;

			PAL_setColors(0, palette_black, 64, DMA_QUEUE); 
			
			VDP_loadTileSet(      bg_gameover_bga.tileset,gInd_tileset,DMA_QUEUE); 
			VDP_setTileMapEx(BG_A,bg_gameover_bga.tilemap,TILE_ATTR_FULL(PAL1,FALSE,FALSE,FALSE,gInd_tileset),0,0,0,0,64,28,DMA_QUEUE);
			PAL_setPalette(PAL1,  bg_gameover_bga.palette->data,DMA_QUEUE);
			gInd_tileset +=       bg_gameover_bga.tileset->numTile;
		}

		if( (gFrames>=VelocidadeTransicao*2) || ((P[1].key_JOY_START_status==1 || P[2].key_JOY_START_status==1) && gFrames>=5) )
		{
			// PAL_fadeOut(0, 63, FADE_TIME, FALSE);
			// CLEAR_VDP();
			// SPR_init();
			// PAL_setColors(0, palette_black, 64, DMA);
			// gFrames=0;
			// gRoom=R_TELA_APRESENTACAO;
			
			SYS_reset();

			running = FALSE;
		}

		//Atualizacao
        SPR_update();
        SYS_doVBlankProcess(); //Wait for screen refresh and do all SGDK VBlank tasks
	}
}

